// PlanetCompute website: one Cloudflare Worker file, no build step, no other files.
//
// Routes
//   /                                  the website
//   /favicon.png, /favicon.ico         48 px PlanetCompute logo (companyLogo/PlanetComputeCompanyLogoNoBG.png)
//   /apple-touch-icon.png              180 px logo (iPhone home screen)
//   /logo.webp                         512 px logo
//   /download/planetComputeClient.exe  302 to env.CLIENT_DOWNLOAD_URL when set,
//                                      otherwise a "coming soon" page
//   /healthz                           "ok"
//   /api/...                           accounts: email sign-in with one-time codes (see "Accounts" below)
//
// Deploy:  Cloudflare dashboard > Workers & Pages > planetcompute > Edit code: replace everything with
//          this file and click Deploy. (Or: npx wrangler deploy BrowserCFWorkerCode/worker.js --name planetcompute)
//          Secrets and variables set on the Worker are kept when the code is replaced.
// Optional: set CLIENT_DOWNLOAD_URL (e.g. a public Backblaze B2 file URL) as a Worker variable.

const FAVICON_PNG_B64 = "";
const TOUCH_PNG_B64 = "";
const LOGO_WEBP_B64 = "";

// Demo WorkPack (133 bytes, hand-assembled): export pc_mc_pi(seed: i32, n: i32) -> i32,
// the number of n xorshift32 points inside the quarter circle. No imports: pure arithmetic.
// WORKPACK_SRC_BEGIN (scripts/embed_workpack.mjs from website/workpack_kernel.mjs + workpack_device.mjs; do not edit here)
const WORKPACK_SRC = "// The browser's WorkPack kernels (docs/SHERPAHUB.md section 3): bit-identical to client/workpack/src/kernels.rs.\n// Embedded in the contributor page in stage 3; tested now by scripts/test_workpack_vectors.mjs.\n// matmul_i8: C (m x n, Int32Array, row-major) = A (m x k, Int8Array) x B, with B given transposed as BT (n x k).\n// Int32 maths throughout (Math.imul and |0), so every JavaScript engine gives the same exact result.\n\nfunction matmulI8(a, bt, m, k, n, c) {\n  if (a.length !== m * k || bt.length !== n * k || c.length !== m * n || k > 131071) throw new Error(\"matmulI8: bad sizes\");\n  const n4 = n - (n % 4);\n  for (let i = 0; i < m; i++) {\n    const ar = i * k, cr = i * n;\n    let j = 0;\n    for (; j < n4; j += 4) {\n      const b0 = j * k, b1 = b0 + k, b2 = b1 + k, b3 = b2 + k;\n      let s0 = 0, s1 = 0, s2 = 0, s3 = 0;\n      for (let t = 0; t < k; t++) {\n        const x = a[ar + t];\n        s0 = (s0 + Math.imul(x, bt[b0 + t])) | 0;\n        s1 = (s1 + Math.imul(x, bt[b1 + t])) | 0;\n        s2 = (s2 + Math.imul(x, bt[b2 + t])) | 0;\n        s3 = (s3 + Math.imul(x, bt[b3 + t])) | 0;\n      }\n      c[cr + j] = s0; c[cr + j + 1] = s1; c[cr + j + 2] = s2; c[cr + j + 3] = s3;\n    }\n    for (; j < n; j++) {\n      const b0 = j * k;\n      let s = 0;\n      for (let t = 0; t < k; t++) s = (s + Math.imul(a[ar + t], bt[b0 + t])) | 0;\n      c[cr + j] = s;\n    }\n  }\n  return c;\n}\n\n// xorshift32 (seed 0 -> 0x9E3779B9), the inputs of tests and synthetic jobs; an int8 is the top byte.\nfunction rngFillI8(seed, out) {\n  let x = (seed >>> 0) || 0x9E3779B9;\n  for (let i = 0; i < out.length; i++) {\n    x ^= x << 13; x >>>= 0; x ^= x >>> 17; x ^= x << 5; x >>>= 0;\n    out[i] = (x >>> 24) << 24 >> 24;\n  }\n  return out;\n}\n\nconst VECTORS = [[1, 1, 1, 1], [7, 4, 16, 4], [42, 17, 33, 9], [1234, 64, 64, 64], [99, 3, 4096, 5], [2026, 61, 301, 67]];\n\nfunction vectorInputs(seed, m, k, n) {\n  return [rngFillI8(seed, new Int8Array(m * k)), rngFillI8((seed ^ 0xA5A5A5A5) >>> 0, new Int8Array(n * k))];\n}\n\n// ---- WebAssembly SIMD kernel (website/workpack_kernel.wat): the fast path where the engine supports SIMD ----\n// WASM_SIMD_BEGIN (scripts/build_workpack_wasm.mjs from website/workpack_kernel.wat; 655 bytes, sha256 fd1eeedb13da1f6ec843886b55831fba88765e9ee4731db37808b84ef7f6049d)\nconst WASM_SIMD_B64 = \"\";\n// WASM_SIMD_END\n\nconst b64bytes = (s) => (typeof atob === \"function\" ? Uint8Array.from(atob(s), (c) => c.charCodeAt(0)) : new Uint8Array(Buffer.from(s, \"base64\")));\n\n// One instance per worker thread. Inputs are copied into its memory (A, then BT, then C, 16-byte aligned); memory\n// grows only when a pack is larger than any before. Returns null where WebAssembly SIMD is not available (old\n// engines): the caller then uses matmulI8 (plain JS), which gives the same exact result.\nfunction makeSimdMatmul() {\n  if (typeof WebAssembly !== \"object\" || !WASM_SIMD_B64) return null;\n  const bytes = b64bytes(WASM_SIMD_B64);\n  if (!WebAssembly.validate(bytes)) return null;\n  const inst = new WebAssembly.Instance(new WebAssembly.Module(bytes), {});\n  const mem = inst.exports.mem, mm = inst.exports.matmul;\n  const al = (x) => (x + 15) & ~15;\n  return function matmulSimd(a, bt, m, k, n, c) {\n    if (a.length !== m * k || bt.length !== n * k || c.length !== m * n || k > 131071) throw new Error(\"matmulSimd: bad sizes\");\n    const pa = 0, pb = al(pa + m * k), pc = al(pb + n * k), end = pc + m * n * 4;\n    if (end > mem.buffer.byteLength) mem.grow(Math.ceil((end - mem.buffer.byteLength) / 65536));\n    const u8 = new Int8Array(mem.buffer);\n    u8.set(a, pa);\n    u8.set(bt, pb);\n    mm(pa, pb, pc, m, k, n);\n    c.set(new Int32Array(mem.buffer, pc, m * n));\n    return c;\n  };\n}\n\n// The browser's SherpaHub device (docs/SHERPAHUB.md section 10) = client/workpack/src/device.rs in JavaScript: keeps\n// the hub's blocks (checked by SHA-256, least recently used dropped first), answers a PACK with RESULT, or with NEED\n// when blocks are missing. Wire format: docs/SHERPAHUB.md section 4 (client/workpack/src/wire.rs).\n// Embedded in the contributor page next to workpack_kernel.mjs (scripts/embed_workpack.mjs); tested in Node by\n// scripts/test_sherpa_e2e.mjs against the real SherpaHub. No backslashes, backticks or dollar-braces in this file:\n// it is placed inside the site's page template.\n//\n// makeSherpaDevice({ cacheBytes, sha256, compute, send, rest })\n//   sha256(Uint8Array) -> Promise<Uint8Array(32)>          (crypto.subtle in the page)\n//   compute(units)     -> Promise<Int32Array[]>             units: [{ unit, m, k, n, a: Int8Array, bt: Int8Array }]\n//   send(Uint8Array)                                        to the hub\n//   rest(ms)           -> Promise                          after each computed pack (the CPU cap)\n// .push(ArrayBuffer) handles messages strictly in order (a BLOCK is stored before the PACK that uses it).\n\nconst PCWP_MAGIC = 0x50574350;\nconst KIND_PACK = 1, KIND_RESULT = 2, KIND_NEED = 3, KIND_BLOCK = 4, KERNEL_MATMUL_I8 = 2, DIM_MAX = 4096;\n\nfunction makeSherpaDevice(o) {\n  const blocks = new Map();                  // id hex -> Int8Array; Map order = least recently used first\n  let used = 0, chain = Promise.resolve();\n  const stats = { blocks: 0, packs: 0, units: 0, needs: 0, refused: 0, ms: 0 };\n  const hex = (b, s, e) => { let h = \"\"; for (let i = s; i < e; i++) h += (b[i] < 16 ? \"0\" : \"\") + b[i].toString(16); return h; };\n  const touch = (id) => { const v = blocks.get(id); blocks.delete(id); blocks.set(id, v); return v; };\n  function header(kind, len) {\n    const out = new Uint8Array(len), v = new DataView(out.buffer);\n    v.setUint32(0, PCWP_MAGIC, true); out[4] = kind; out[5] = 1;\n    return { out, v };\n  }\n  async function onBlock(b, v) {\n    if (b.length < 28) return stats.refused++;\n    const len = v.getUint32(24, true);\n    if (len === 0 || 28 + len !== b.length || len > o.cacheBytes) return stats.refused++;\n    const bytes = b.slice(28), d = await o.sha256(bytes);\n    for (let i = 0; i < 16; i++) if (d[i] !== b[8 + i]) return stats.refused++;   // corrupted: never used\n    const id = hex(b, 8, 24);\n    if (blocks.has(id)) return;\n    while (used + len > o.cacheBytes && blocks.size) { const [k, x] = blocks.entries().next().value; blocks.delete(k); used -= x.length; }\n    blocks.set(id, new Int8Array(bytes.buffer)); used += len; stats.blocks++;\n  }\n  async function onPack(b, v) {\n    const count = b[29];\n    if (b.length < 32 || b[28] !== KERNEL_MATMUL_I8 || count === 0 || b.length !== 32 + count * 48) return stats.refused++;\n    const units = [], missing = [];\n    for (let i = 0, p = 32; i < count; i++, p += 48) {\n      const u = { unit: v.getUint32(p, true), m: v.getUint32(p + 4, true), k: v.getUint32(p + 8, true), n: v.getUint32(p + 12, true), ia: hex(b, p + 16, p + 32), ib: hex(b, p + 32, p + 48), pa: p + 16, pb: p + 32 };\n      if (!u.m || !u.k || !u.n || u.m > DIM_MAX || u.k > DIM_MAX || u.n > DIM_MAX) return stats.refused++;\n      for (const [id, at] of [[u.ia, u.pa], [u.ib, u.pb]]) if (!blocks.has(id) && !missing.some((x) => x[0] === id)) missing.push([id, at]);\n      units.push(u);\n    }\n    if (missing.length) {                     // NEED: job, pack, epoch (bytes 8..28 of the PACK), count, ids\n      const { out, v: w } = header(KIND_NEED, 32 + missing.length * 16);\n      out.set(b.subarray(8, 28), 8); w.setUint32(28, missing.length, true);\n      missing.forEach(([, at], i) => out.set(b.subarray(at, at + 16), 32 + i * 16));\n      stats.needs++; o.send(out); return;\n    }\n    for (const u of units) {\n      u.a = touch(u.ia); u.bt = touch(u.ib);\n      if (u.a.length !== u.m * u.k || u.bt.length !== u.n * u.k) return stats.refused++;   // sizes do not match its blocks\n    }\n    const t0 = Date.now(), cs = await o.compute(units), ms = Date.now() - t0;\n    let len = 36;\n    units.forEach((u) => { len += 12 + u.m * u.n * 4; });\n    const { out, v: w } = header(KIND_RESULT, len);\n    out.set(b.subarray(8, 28), 8); w.setUint32(28, Math.min(ms, 0xffffffff), true); out[32] = count;\n    let p = 36;\n    units.forEach((u, i) => {\n      w.setUint32(p, u.unit, true); w.setUint32(p + 4, u.m, true); w.setUint32(p + 8, u.n, true); p += 12;\n      const c = cs[i];\n      for (let j = 0; j < c.length; j++, p += 4) w.setInt32(p, c[j], true);\n    });\n    stats.packs++; stats.units += count; stats.ms += ms;\n    o.send(out);\n    if (o.rest) await o.rest(ms);\n  }\n  async function handle(buf) {\n    const b = new Uint8Array(buf), v = new DataView(b.buffer, b.byteOffset, b.byteLength);\n    if (b.length < 8 || v.getUint32(0, true) !== PCWP_MAGIC || b[5] !== 1) return stats.refused++;\n    if (b[4] === KIND_BLOCK) return onBlock(b, v);\n    if (b[4] === KIND_PACK) return onPack(b, v);\n    stats.refused++;\n  }\n  return {\n    stats,\n    cached: () => blocks.size,\n    push(buf) { chain = chain.then(() => handle(buf)).catch(() => { stats.refused++; }); return chain; },\n  };\n}\n";
// WORKPACK_SRC_END
const DEMO_WASM_B64 = "AGFzbQEAAAABBwFgAn9/AX8DAgEABwwBCHBjX21jX3BpAAAKYAFeAQJ/AkADQCABRQ0BIAAgAEENdHMhACAAIABBEXZzIQAgACAAQQV0cyIAQf//AXEiAyADbCAAQQ92Qf//AXEiAyADbGpBgICAgARJIAJqIQIgAUEBayEBDAALCyACCw==";

const SECURITY_HEADERS = {
  "x-content-type-options": "nosniff",
  "referrer-policy": "strict-origin-when-cross-origin",
  "x-frame-options": "DENY",
  "permissions-policy": "camera=(), microphone=(), geolocation=()",
  "content-security-policy":
    "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; " +
    "font-src https://fonts.gstatic.com; script-src 'self' 'unsafe-inline' 'wasm-unsafe-eval' https://cdn.jsdelivr.net https://challenges.cloudflare.com; " +
    "frame-src 'self' https://challenges.cloudflare.com https://device.planetcompute.ai; worker-src blob:; connect-src 'self' https://*.planetcompute.ai; frame-ancestors 'none'",
};

function bytes(b64) {
  const s = atob(b64);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

function asset(b64, type) {
  return new Response(bytes(b64), {
    headers: { "content-type": type, "cache-control": "public, max-age=604800, immutable" },
  });
}

// Lets phones add the site to the home screen and open it full screen, like an app.
const MANIFEST = {
  name: "PlanetCompute", short_name: "PlanetCompute", start_url: "/", scope: "/", display: "standalone",
  background_color: "#070b1a", theme_color: "#070b1a", description: "Share compute, receive compute.",
  icons: [{ src: "/logo.webp?v=2", sizes: "512x512", type: "image/webp", purpose: "any" }, { src: "/apple-touch-icon.png?v=2", sizes: "180x180", type: "image/png" }, { src: "/favicon.png?v=2", sizes: "48x48", type: "image/png" }],
};

function html(body, status = 200) {
  return new Response(body, {
    status,
    headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300", ...SECURITY_HEADERS },
  });
}

export default {
  // Cron Trigger (wrangler.toml [triggers]): hourly heartbeat-server check and the "no server running" email
  async scheduled(event, env, ctx) {
    if (event && event.cron === SEAL_CRON) { ctx.waitUntil(sealCron(env || {}).catch((e) => console.log("seal cron", e && e.message))); return; }
    if (event && event.cron === "47 * * * *") { ctx.waitUntil(myCron(env || {}).catch((e) => console.log("my cron", e && e.message))); return; }   // my.planetcompute.ai views
    ctx.waitUntil(hbCron(env || {}).catch((e) => console.log("hb cron", e && e.message)));
  },
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.hostname === deviceHost(env || {})) return handleDeviceHost(request, env || {}, url);   // device pages only (security review T1)
    if (url.pathname === "/api/pool/chat") return handleJobs(request, env || {});   // the program's "PlanetCompute pool" (same grid)
    if (url.pathname === "/api/pool" && request.method === "GET") return poolInfo(request, env || {});
    if (url.pathname === "/api/pool/media" || url.pathname === "/api/pool/media/file" || url.pathname === "/api/pool/media/cancel") return poolMedia(request, env || {}, url);   // pictures and videos
    if (url.pathname === "/express" || url.pathname.startsWith("/express/")) return handleExpress(request, env || {}, url);   // Receive Compute, no PC: the program page on the pool
    if (url.pathname === "/api/view") return mediaView(request, env || {}, url);   // my.planetcompute.ai view count (no database)
    if (MY_CORS_PATHS.includes(url.pathname) && request.headers.get("origin") === MY_ORIGIN) return myCors(request, env || {}, url);
    if (url.pathname.startsWith("/api/")) return handleApi(request, env || {}, url);
    if (url.pathname === "/v1/jobs") return handleJobs(request, env || {});
    if (url.pathname.startsWith("/device/")) return handleDevice(request, env || {}, url);
    if (url.pathname === "/temp" || url.pathname.startsWith("/temp/")) return handleTemp(request, env || {}, url);
    if (url.pathname.startsWith("/u/")) return handleUserFile(request, env || {}, url);
    // "Report abuse" on a shared picture or video: the contact form with that topic and the link filled in
    if (url.pathname === "/reportabuse") return Response.redirect(`${url.origin}/?report=${encodeURIComponent((url.searchParams.get("url") || "").slice(0, 300))}#ask`, 302);
    switch (url.pathname) {
      case "/":
      case "/index.html":
      case "/contribute":                 // the volunteer side; the home page defaults to it
      case "/contribute/": {
        if (url.searchParams.get("console") !== "1") return html(PAGE);
        // the volunteer console alone, shown inside the planetCompute program's Contribute tab (same origin only)
        const r = html(PAGE);
        r.headers.set("x-frame-options", "SAMEORIGIN");
        r.headers.set("content-security-policy", SECURITY_HEADERS["content-security-policy"].replace("frame-ancestors 'none'", "frame-ancestors 'self'"));
        return r;
      }
      case "/favicon.png":
      case "/favicon.ico":
        return asset(FAVICON_PNG_B64, "image/png");
      case "/apple-touch-icon.png":
        return asset(TOUCH_PNG_B64, "image/png");
      case "/logo.webp":
        return asset(LOGO_WEBP_B64, "image/webp");
      case "/harness":                    // the consumer side (coming soon page for now); shown inside the site too
      case "/harness/": {
        const r = html(HARNESS_COMPUTE);
        r.headers.set("x-frame-options", "SAMEORIGIN");
        r.headers.set("content-security-policy", SECURITY_HEADERS["content-security-policy"].replace("frame-ancestors 'none'", "frame-ancestors 'self'"));
        return r;
      }
      case "/download":
      case "/download/":
        return handleDownload(request, env || {}, url, "");
      case "/download/planetComputeClient.exe":     // the old link on the home page
        return Response.redirect(`${url.origin}/download/windows`, 302);
      case "/download/windows":
      case "/download/mac":
      case "/download/linux":
      case "/download/linux-vulkan":
      case "/download/linux-server":
      case "/download/latest.json":                 // versions and SHA-256 of every build (servers' agents update from it)
        return handleDownload(request, env || {}, url, url.pathname.slice("/download/".length));
      case "/admin": {                    // shown inside the site (same origin only) so a running console keeps running
        const r = html(ADMIN_PAGE);
        r.headers.set("x-frame-options", "SAMEORIGIN");
        r.headers.set("content-security-policy", SECURITY_HEADERS["content-security-policy"].replace("frame-ancestors 'none'", "frame-ancestors 'self'"));
        return r;
      }
      case "/balance":
      case "/balance/":
        return html(BALANCE_PAGE);
      case "/docs":                       // Documentation and Disclaimer (website/docs_content.html, also in the program)
      case "/docs/":
      case "/documentation":
        return html(DOCS_PAGE);
      case "/mycontent":
      case "/mycontent/": {               // also shown inside Harness Compute, Cloud Content (same origin only)
        const r = html(MYCONTENT_PAGE);
        r.headers.set("x-frame-options", "SAMEORIGIN");
        r.headers.set("content-security-policy", SECURITY_HEADERS["content-security-policy"].replace("frame-ancestors 'none'", "frame-ancestors 'self'"));
        return r;
      }
      case "/manifest.webmanifest":
        return new Response(JSON.stringify(MANIFEST), { headers: { "content-type": "application/manifest+json", "cache-control": "public, max-age=86400" } });
      case "/healthz":
        return new Response("ok", { headers: { "content-type": "text/plain" } });
      default:
        return html(NOT_FOUND, 404);
    }
  },
};

// ---------------------------------------------------------------------------
// Accounts: email sign-in with one-time codes (no passwords).
//
// Worker secrets / variables (set in the Cloudflare dashboard or with `npx wrangler secret put NAME`):
//   AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY   DynamoDB access to the <prefix>* tables
//   AWS_REGION            default us-east-1
//   DDB_PREFIX            optional, default planetcompute-ai-   (table <prefix>user, see CreateTables.py)
//   SESSION_SECRET        long random string; salts the stored hashes of codes and session tokens
//   RESEND_API_KEY, RESEND_FROM   the codes are emailed through Resend (https://resend.com) from RESEND_FROM
//   (fallback when RESEND_API_KEY is not set: Amazon SES from MAIL_FROM)
//
// API (JSON in, JSON out; same-origin only)
//   POST /api/auth/start         {email}          email a 6-digit code (always answers ok)
//   POST /api/auth/verify        {email, code}    sign in, creating the account on first use; sets the session cookie
//   POST /api/auth/signout                        end this session
//   GET  /api/me                                  {user_id, primary_email, emails[]} or 401
//   POST /api/me/profile         {first_name, last_name}   save the name on the profile (up to 50 characters each)
//   POST /api/me/solana-address  {address}  the account's Solana wallet address (the old one goes to <prefix>address-audit)
//   GET  /api/me/solana-address/history      the addresses used before, newest first
//   POST /api/volunteer/heartbeat {device_id, session_id, state, ...}  a signed-in volunteer's status, once a minute;
//                                 logged in <prefix>Contributor-Sessions and credited (see heartbeat())
//   GET  /api/credit-rate                         the award rule in force now, and the next scheduled one (public)
//   GET  /api/admin/users | /api/admin/devices | /api/admin/credits | /api/admin/contributor-sessions
//        ?limit=10..200&cursor=<from the previous page>&q=<search>&filter=<all|admins|active>   admin only, one page each
//   GET  /api/admin/credit-rules | /api/admin/ratings | /api/admin/epochs                          admin only
//   POST /api/admin/credit-rules/create {effective_from, credit_per_wu, first_finisher_share, standby_per_hour,
//        work_min_per_hour, note}  (future only)
//   POST /api/admin/credit-rules/cancel {rule_id}   (only rules that have not taken effect)
//   POST /api/admin/users/create {email, first_name, last_name}   POST /api/admin/users/delete {user_id}
//   POST /api/me/emails/start    {email}          email a code to an address to add
//   POST /api/me/emails/verify   {email, code}    add the address to this account
//   POST /api/me/emails/primary  {email}          make an address the primary one
//   POST /api/me/emails/remove   {email}          remove an address (never the last one)

const CODE_TTL_S = 10 * 60;            // a code is valid for 10 minutes
const CODE_MAX_ATTEMPTS = 5;           // wrong guesses before the code is void
const CODE_RESEND_S = 30;              // minimum gap between two codes to one address
const CODE_MAX_PER_HOUR = 5;           // codes per address per hour
const SESSION_TTL_S = 30 * 24 * 3600;  // sessions last 30 days
const COOKIE = "pc_session";

const enc = new TextEncoder();
const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
const sha256hex = async (s) => hex(await crypto.subtle.digest("SHA-256", typeof s === "string" ? enc.encode(s) : s));
async function hmac(key, data) {
  const k = await crypto.subtle.importKey("raw", typeof key === "string" ? enc.encode(key) : key,
    { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return crypto.subtle.sign("HMAC", k, enc.encode(data));
}
const randomBytes = (n) => crypto.getRandomValues(new Uint8Array(n));
const b64url = (u8) => btoa(String.fromCharCode(...u8)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const now = () => Math.floor(Date.now() / 1000);
const iso = () => new Date().toISOString();

function newUserId() { return hex(randomBytes(6)); }            // 12 hex digits = 48 random bits
function newCode() {                                             // uniform 6-digit code
  for (;;) { const v = crypto.getRandomValues(new Uint32Array(1))[0]; if (v < 4294000000) return String(v % 1000000).padStart(6, "0"); }
}
function normEmail(e) {
  e = String(e || "").trim().toLowerCase();
  return e.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) ? e : null;
}

// --- AWS Signature Version 4 (DynamoDB and SES v2 over HTTPS) ---
async function awsRequest(env, service, host, path, headers, body) {
  const region = env.AWS_REGION || "us-east-1";
  const t = new Date().toISOString().replace(/[:-]|\.\d{3}/g, "");   // YYYYMMDDTHHMMSSZ
  const day = t.slice(0, 8);
  const h = { ...headers, host, "x-amz-date": t };
  const names = Object.keys(h).map((k) => k.toLowerCase()).sort();
  const lower = Object.fromEntries(Object.entries(h).map(([k, v]) => [k.toLowerCase(), String(v).trim()]));
  const signed = names.join(";");
  const canonical = ["POST", path, "", names.map((k) => `${k}:${lower[k]}\n`).join(""), signed, await sha256hex(body)].join("\n");
  const scope = `${day}/${region}/${service}/aws4_request`;
  const toSign = ["AWS4-HMAC-SHA256", t, scope, await sha256hex(canonical)].join("\n");
  let key = await hmac("AWS4" + env.AWS_SECRET_ACCESS_KEY, day);
  for (const part of [region, service, "aws4_request"]) key = await hmac(key, part);
  const sig = hex(await hmac(key, toSign));
  const auth = `AWS4-HMAC-SHA256 Credential=${env.AWS_ACCESS_KEY_ID}/${scope}, SignedHeaders=${signed}, Signature=${sig}`;
  return fetch(`https://${host}${path}`, { method: "POST", headers: { ...h, authorization: auth }, body });
}

class DdbError extends Error { constructor(type, msg) { super(msg); this.type = type; } }
async function ddb(env, op, payload) {
  const region = env.AWS_REGION || "us-east-1";
  const r = await awsRequest(env, "dynamodb", `dynamodb.${region}.amazonaws.com`, "/",
    { "content-type": "application/x-amz-json-1.0", "x-amz-target": `DynamoDB_20120810.${op}` }, JSON.stringify(payload));
  const j = await r.json();
  if (!r.ok) {
    const type = String(j.__type || "").split("#").pop();
    throw new DdbError(type, j.message || j.Message || type);
  }
  return j;
}
const decStr = (n) => Number.isInteger(n) ? String(n) : n.toFixed(20).replace(/0+$/, "").replace(/\.$/, "");
const M = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined)
  .map(([k, v]) => [k, typeof v === "number" ? { N: decStr(v) } : typeof v === "boolean" ? { BOOL: v } : { S: String(v) }]));
const U = (item) => item && Object.fromEntries(Object.entries(item).map(([k, v]) =>
  [k, "N" in v ? Number(v.N) : "BOOL" in v ? v.BOOL : v.S]));
const PFX = (env) => env.DDB_PREFIX || "planetcompute-ai-";
const tableName = (env) => PFX(env) + "user";
const sessionsTable = (env) => PFX(env) + "Contributor-Sessions";

// --- indexes for millions of rows (see CreateTables.py). Every admin list is a Query on a KEYS_ONLY global
// secondary index followed by one BatchGetItem for the page, never a Scan. Index partitions are spread by
// time (month or day) so no partition key is written more than a few times a second; the fast-changing
// "live" index is also split into shards. Index attributes that do not change cost no index writes.
const START_MONTH = "2026-10";                 // the first month with data: listings walk back to here
// the active-device index moves a device once per 20 minutes (>= ACTIVE_S: "now" reads this bucket and the one before)
const LIVE_BUCKET_S = 1200, LIVE_SHARDS = 8;
function monthsBack(fromIso) {
  const out = [];
  let [y, m] = fromIso.slice(0, 7).split("-").map(Number);
  for (;;) {
    const k = `${y}-${String(m).padStart(2, "0")}`;
    if (k < START_MONTH) return out;
    out.push(k);
    if (--m === 0) { m = 12; y--; }
  }
}
function daysBack(fromIso) {
  const out = [], first = START_MONTH + "-01";
  for (let d = Date.parse(fromIso.slice(0, 10) + "T00:00:00Z"); ; d -= 86400000) {
    const k = new Date(d).toISOString().slice(0, 10);
    if (k < first) return out;
    out.push(k);
  }
}
const liveKeys = (t) => { const b = Math.floor(t / LIVE_BUCKET_S) * LIVE_BUCKET_S;
  return Array.from({ length: LIVE_SHARDS }, (_, i) => `LIVE#${b}#${i}`); };
const liveKey = (t, deviceId) => `LIVE#${Math.floor(t / LIVE_BUCKET_S) * LIVE_BUCKET_S}#${parseInt(deviceId.slice(-4), 16) % LIVE_SHARDS}`;
// Search keys: lower-case, letters and digits only; the first two characters pick the index partition.
const searchKey = (v) => String(v || "").toLowerCase().normalize("NFKD").replace(/[^a-z0-9@._ -]/g, "").trim();
function nameIndex(first, last) {               // attributes for the users-by-first-name / -last-name indexes
  const f = searchKey(first), l = searchKey(last), out = {}, drop = [];
  if (f.length >= 1) { out.fname_pk = "FN#" + f.slice(0, 2); out.fname_sk = `${f} ${l}`.trim(); } else drop.push("fname_pk", "fname_sk");
  if (l.length >= 1) { out.lname_pk = "LN#" + l.slice(0, 2); out.lname_sk = `${l} ${f}`.trim(); } else drop.push("lname_pk", "lname_sk");
  return { set: out, remove: drop };
}
const emailIndex = (email) => ({ eml_pk: "EM#" + email.slice(0, 2), eml_sk: email });
const encCursor = (c) => (c ? b64url(enc.encode(JSON.stringify(c))) : null);
function decCursor(s) {
  if (!s) return null;
  try { return JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(String(s).replace(/-/g, "+").replace(/_/g, "/")), (ch) => ch.charCodeAt(0)))); }
  catch { return null; }
}
// Walk index partitions in order (newest first), taking up to `limit` keys; the cursor remembers the
// partition and DynamoDB's LastEvaluatedKey, so the next page continues exactly where this one stopped.
async function walkIndex(env, { table, index, pkAttr, pks, limit, cursor, maxQueries = 8, forward = false }) {
  let i = 0, lek;
  if (cursor && cursor.p) { i = pks.indexOf(cursor.p); lek = cursor.k || undefined; if (i < 0) return { keys: [], next: null }; }
  const keys = [];
  for (let q = 0; i < pks.length && keys.length < limit && q < maxQueries; q++) {
    const r = await ddb(env, "Query", { TableName: table, IndexName: index, KeyConditionExpression: "#p = :p",
      ExpressionAttributeNames: { "#p": pkAttr }, ExpressionAttributeValues: { ":p": S_(pks[i]) },
      ScanIndexForward: forward, Limit: limit - keys.length, ...(lek ? { ExclusiveStartKey: lek } : {}) });
    keys.push(...(r.Items || []));
    if (r.LastEvaluatedKey) lek = r.LastEvaluatedKey; else { i++; lek = undefined; }
  }
  return { keys, next: i < pks.length ? { p: pks[i], k: lek || null } : null };
}
// BatchGetItem in chunks of 100, retrying unprocessed keys; returns plain items in the order of `keys`.
async function batchGet(env, table, keyNames, keys) {
  const id = (k) => keyNames.map((n) => (k[n].S !== undefined ? k[n].S : k[n].N)).join("\u0001");
  const uniq = [...new Map(keys.map((k) => [id(k), Object.fromEntries(keyNames.map((n) => [n, k[n]]))])).values()];
  const found = new Map();
  for (let i = 0; i < uniq.length; i += 100) {
    let req = { [table]: { Keys: uniq.slice(i, i + 100) } };
    for (let tries = 0; tries < 6 && req && req[table]; tries++) {
      const r = await ddb(env, "BatchGetItem", { RequestItems: req });
      for (const it of (r.Responses || {})[table] || []) found.set(id(it), U(it));
      req = r.UnprocessedKeys && r.UnprocessedKeys[table] ? r.UnprocessedKeys : null;
      if (req) await new Promise((res) => setTimeout(res, 100 * (tries + 1)));
    }
  }
  return keys.map((k) => found.get(id(k))).filter(Boolean);
}
// Running totals for the admin page (one small item; changed only when accounts, devices or sessions are added).
const bumpStats = (env, field, by) => ddb(env, "UpdateItem", { TableName: tableName(env), Key: M({ pk: "STATS", sk: "COUNTS" }),
  UpdateExpression: "ADD #f :n SET updated_at = :t", ExpressionAttributeNames: { "#f": field }, ExpressionAttributeValues: M({ ":n": by, ":t": iso() }) })
  .catch((e) => console.log("stats", e && e.message));
async function getItem(env, pk, sk) {
  return U((await ddb(env, "GetItem", { TableName: tableName(env), Key: M({ pk, sk }), ConsistentRead: true })).Item);
}

// Who asked for the code (user 2026-11-01: codes kept arriving): IP address, approximate place, browser or program, time
function codeRequestedFrom(request) {
  if (!request) return "";
  const cf = request.cf || {}, ip = request.headers.get("cf-connecting-ip") || "unknown";
  const place = [cf.city, cf.region, cf.country].filter(Boolean).join(", ");
  const ua = request.headers.get("user-agent") || "";
  const app = /^planetCompute\//.test(ua) ? "the planetCompute program (" + ua.split(" ")[0] + ")"
    : /Edg\//.test(ua) ? "Microsoft Edge" : /OPR\//.test(ua) ? "Opera" : /Firefox\//.test(ua) ? "Firefox" : /Chrome\//.test(ua) ? "Chrome"
    : /Safari\//.test(ua) ? "Safari" : ua ? ua.slice(0, 60) : "an unknown program";
  const os = /Windows/.test(ua) ? " on Windows" : /Mac OS X|Macintosh/.test(ua) ? " on macOS" : /Android/.test(ua) ? " on Android"
    : /iPhone|iPad/.test(ua) ? " on iOS" : /Linux/.test(ua) ? " on Linux" : "";
  return `Requested from IP address ${ip}${place ? " (" + place + ")" : ""}, using ${app}${os}, at ${iso().slice(0, 16).replace("T", " ")} UTC.`;
}
async function sendCodeEmail(env, to, code, purpose, request) {
  const from = codeRequestedFrom(request);
  const region = env.AWS_REGION || "us-east-1";
  const what = purpose.startsWith("add") ? "add this email address to your PlanetCompute account" : purpose === "wallet" ? "confirm a new Solana wallet address on your PlanetCompute account (transfers go there)"
    : purpose === "move" ? "confirm sending coins from a PlanetCompute wallet (admin)" : "sign in to PlanetCompute";
  const text = `Your PlanetCompute code is ${code}\n\nUse it to ${what}. It expires in 10 minutes and can be used once.\n` +
    (from ? from + "\n" : "") + `If you did not ask for it, ignore this email: nothing happens without the code.${purpose === "wallet" || purpose === "move" ? " Someone may have your sign-in: sign out everywhere and tell us." : ""}\n\nhttps://planetcompute.ai`;
  const htmlBody = `<div style="font-family:Arial,sans-serif;max-width:480px;margin:auto;padding:24px;color:#14182b">` +
    `<h2 style="margin:0 0 12px">Your PlanetCompute code</h2><p>Use this code to ${what}:</p>` +
    `<p style="font-size:32px;font-weight:700;letter-spacing:6px;margin:18px 0">${code}</p>` +
    `<p>It expires in 10 minutes and can be used once. If you did not ask for it, ignore this email: nobody can sign in without the code.</p>` +
    (from ? `<p style="color:#445;font-size:13px">${escHtml(from)}</p>` : "") +
    `<p style="color:#667;font-size:13px">PlanetCompute · https://planetcompute.ai</p></div>`;
  const subject = `${code} is your PlanetCompute code`;
  if (env.RESEND_API_KEY) {
    const r = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { authorization: `Bearer ${env.RESEND_API_KEY}`, "content-type": "application/json" },
      body: JSON.stringify({ from: env.RESEND_FROM, to: [to], subject, text, html: htmlBody }),
    });
    if (!r.ok) throw new Error("email not sent (Resend " + r.status + "): " + (await r.text()).slice(0, 300));
    return;
  }
  const body = JSON.stringify({
    FromEmailAddress: env.MAIL_FROM || "PlanetCompute <noreply@planetcompute.ai>",
    Destination: { ToAddresses: [to] },
    Content: { Simple: { Subject: { Data: subject },
      Body: { Text: { Data: text }, Html: { Data: htmlBody } } } },
  });
  const r = await awsRequest(env, "ses", `email.${region}.amazonaws.com`, "/v2/email/outbound-emails",
    { "content-type": "application/json" }, body);
  if (!r.ok) throw new Error("email not sent: " + (await r.text()).slice(0, 300));
}

// --- one-time codes ---
const authSecret = (env) => env.SESSION_SECRET || env.AUTH_SECRET;
const codeHash = (env, purpose, email, code) => sha256hex(`${authSecret(env)}|code|${purpose}|${email}|${code}`);

// Security review L3: wrong codes per address over a day; at OTP_FAIL_LOCK no new codes for that address until it passes
const OTP_FAIL_LOCK = 15;   // per address per UTC day
// A daily ceiling per address (user 2026-11-01): more than OTP_DAY_MAX code requests for one address within 24 hours
// (every purpose; refused ones count too) put the address on hold for OTP_HOLD_S: no code is made, and ONE email tells
// the address when the hold started. Requests during the hold are refused without another email.
const OTP_DAY_MAX = 10, OTP_HOLD_S = 24 * 3600;   // user 2026-11-01: hold for 24 hours after 10 requests
const gmtStamp = (t) => new Date(t * 1000).toISOString().replace(/\.\d+Z$/, "").replace(/-/g, "").replace("T", ":").replace(/:(\d\d):(\d\d)$/, "$1$2");
async function otpDayCheck(env, email, t) {
  const pk = `OTPREQ#${email}`, rq = await getItem(env, pk, "OTPREQ");
  const holdMsg = (until) => `This account is on hold until ${gmtStamp(until)} Greenwich time (too many code requests in 24 hours). Please try later.`;
  if (rq && Number(rq.hold_until || 0) > t) return { ok: false, status: 429, error: holdMsg(Number(rq.hold_until)) };
  const times = String((rq && rq.times) || "").split(",").map(Number).filter((x) => x > 0 && t - x < 86400);
  times.push(t);
  if (times.length > OTP_DAY_MAX) {
    const until = t + OTP_HOLD_S;
    await ddb(env, "PutItem", { TableName: tableName(env), Item: M({ pk, sk: "OTPREQ", times: "", hold_started: t, hold_until: until, ttl: until + 86400 }) });
    const hours = Math.round(OTP_HOLD_S / 3600);
    const text = `Your account is on hold for ${hours} hours starting ${gmtStamp(t)} Greenwich time; please try later.\n\n` +
      `PlanetCompute received more than ${OTP_DAY_MAX} requests for a sign-in or confirmation code for this address within 24 hours, so no new code will be ` +
      `sent until ${gmtStamp(until)} Greenwich time. If you did not ask for these codes, nobody can sign in without them: you need to do nothing.\n\nPlanetCompute · https://planetcompute.ai`;
    await sendEmail(env, { to: [email], subject: `Your PlanetCompute account is on hold for ${hours} hours`, text,
      html: `<div style="font-family:Arial,sans-serif;max-width:480px;margin:auto;padding:24px;color:#14182b"><h2 style="margin:0 0 12px">Your account is on hold</h2>` +
        `<p><b>Your account is on hold for ${hours} hours starting ${gmtStamp(t)} Greenwich time; please try later.</b></p>` +
        `<p>PlanetCompute received more than ${OTP_DAY_MAX} requests for a sign-in or confirmation code for this address within 24 hours, so no new code will be sent until ${gmtStamp(until)} Greenwich time. ` +
        `If you did not ask for these codes, nobody can sign in without them: you need to do nothing.</p><p style="color:#667;font-size:13px">PlanetCompute · https://planetcompute.ai</p></div>` })
      .catch((e) => console.log("hold email", e && e.message));
    return { ok: false, status: 429, error: holdMsg(until) };
  }
  await ddb(env, "PutItem", { TableName: tableName(env), Item: M({ pk, sk: "OTPREQ", times: times.slice(-OTP_DAY_MAX - 1).join(","), ttl: t + 2 * 86400 }) });
  return null;
}
async function issueCode(env, purpose, email, request) {
  const pk = `OTP#${purpose}#${email}`, t = now();
  const held = await otpDayCheck(env, email, t);
  if (held) return held;
  const fails = await getItem(env, `OTPFAIL#${email}#${Math.floor(t / 86400)}`, "OTPFAIL");   // today's (UTC) wrong codes
  if (fails && Number(fails.n || 0) >= OTP_FAIL_LOCK)
    return { ok: false, status: 429, error: "Too many wrong codes for this address today. Please try again tomorrow." };
  const prev = await getItem(env, pk, "OTP");
  if (prev && t - prev.issued_at < CODE_RESEND_S) return { ok: false, status: 429, error: "Please wait a few seconds before asking for another code." };
  const inWindow = prev && t - prev.window_start < 3600;
  const sends = inWindow ? prev.sends + 1 : 1;
  if (sends > CODE_MAX_PER_HOUR) return { ok: false, status: 429, error: "Too many codes for this address. Try again in an hour." };
  const code = newCode();
  await ddb(env, "PutItem", { TableName: tableName(env), Item: M({
    pk, sk: "OTP", code_hash: await codeHash(env, purpose, email, code), issued_at: t, expires_at: t + CODE_TTL_S,
    attempts: 0, sends, window_start: inWindow ? prev.window_start : t, ttl: t + 3600 + CODE_TTL_S }) });
  try {
    await sendCodeEmail(env, email, code, purpose, request);
  } catch (e) {
    console.log("email send failed", e && e.message);
    // undo, so the volunteer can try again at once and the failed send does not count against the limit
    await ddb(env, "UpdateItem", { TableName: tableName(env), Key: M({ pk, sk: "OTP" }),
      UpdateExpression: "REMOVE code_hash SET issued_at = :z, sends = :s, expires_at = :t",
      ExpressionAttributeValues: M({ ":z": 0, ":s": sends - 1, ":t": t }) });
    return { ok: false, status: 502, error: "We could not send the email just now. Please try again in a minute." };
  }
  return { ok: true };
}

async function checkCode(env, purpose, email, code) {
  const pk = `OTP#${purpose}#${email}`, t = now();
  // Security review W4: use up one attempt FIRST, in one conditional write, so guesses sent at the same moment cannot
  // all pass the "fewer than 5 attempts" check; then compare; then use the code up only if it is still unused.
  try {
    await ddb(env, "UpdateItem", { TableName: tableName(env), Key: M({ pk, sk: "OTP" }), UpdateExpression: "ADD attempts :one",
      ConditionExpression: "attribute_exists(code_hash) AND expires_at > :t AND (attribute_not_exists(attempts) OR attempts < :max)",
      ExpressionAttributeValues: M({ ":one": 1, ":t": t, ":max": CODE_MAX_ATTEMPTS }) });
  } catch (e) {
    if (e.type !== "ConditionalCheckFailedException") throw e;
    const otp = await getItem(env, pk, "OTP");
    return !otp || !otp.code_hash || t > otp.expires_at ? "That code has expired. Ask for a new one." : "Too many wrong codes. Ask for a new one.";
  }
  const otp = await getItem(env, pk, "OTP");
  if (!otp || !otp.code_hash) return "That code has expired. Ask for a new one.";
  const h = /^\d{6}$/.test(String(code || "")) ? await codeHash(env, purpose, email, code) : "";
  if (h !== otp.code_hash) {
    try {
      await ddb(env, "UpdateItem", { TableName: tableName(env), Key: M({ pk: `OTPFAIL#${email}#${Math.floor(t / 86400)}`, sk: "OTPFAIL" }),
        UpdateExpression: "ADD n :one SET #ttl = :x", ExpressionAttributeNames: { "#ttl": "ttl" },
        ExpressionAttributeValues: M({ ":one": 1, ":x": t + 2 * 86400 }) });
    } catch (e) { console.log("otp fail count", e && e.message); }
    return "That code is not right. Check the email and try again.";
  }
  try {                                                  // single use: remove the hash (only if it is still this one)
    await ddb(env, "UpdateItem", { TableName: tableName(env), Key: M({ pk, sk: "OTP" }), UpdateExpression: "REMOVE code_hash SET expires_at = :t",
      ConditionExpression: "code_hash = :h", ExpressionAttributeValues: M({ ":t": t, ":h": h }) });
  } catch (e) { if (e.type === "ConditionalCheckFailedException") return "That code was already used. Ask for a new one."; throw e; }
  return null;
}

// --- users and sessions ---
const MAX_EMAILS = 10;                            // email addresses per account
async function userForEmail(env, email) {
  const m = await getItem(env, `EMAIL#${email}`, "EMAIL");
  return m ? m.user_id : null;
}

// One account per address for the limits: Gmail ignores dots and +tags, most mail services +tags (user 2026-10-30)
function canonEmail(email) {
  let [l, d] = String(email || "").toLowerCase().split("@");
  if (!d) return String(email || "").toLowerCase();
  l = l.split("+")[0];
  if (d === "gmail.com" || d === "googlemail.com") { l = l.replace(/\./g, ""); d = "gmail.com"; }
  return l + "@" + d;
}
// A new account (no account has this address yet): a permanent address, not a second account for the same address,
// a few new accounts a day per IP, and Cloudflare Turnstile (the website shows the check; the program sends people to it)
async function newAccountCheck(env, request, email, body) {
  if (DISPOSABLE_DOMAINS.has(email.split("@")[1])) return json({ error: "Please use a permanent email address." }, 400);
  const other = await getItem(env, `CANON#${canonEmail(email)}`, "CANON");
  if (other) return json({ error: `An account already exists for this address (${maskEmail(other.email || "")}): please sign in with that address.` }, 409);
  const no = await turnstileCheck(env, request, body, "New account: please complete the check below, then press the button again.");
  if (no) return no;
  return authLimit(env, request, "newacct", true);
}
// Cloudflare Turnstile on a sign-in code request (null = passed, or Turnstile is not configured). New accounts always;
// existing accounts too since 2026-11-01 (user: codes for one address kept being requested), except from the
// planetCompute program, whose window cannot show the check: its requests keep the per-address and per-network limits.
async function turnstileCheck(env, request, body, ask) {
  if (!env.TURNSTILE_SECRET) return null;
  if (!body.turnstile) return json({ need_turnstile: true, sitekey: env.TURNSTILE_SITEKEY || "", signup_url: new URL(request.url).origin + "/?auth=signup",
    error: ask }, 428);
  const fd = new FormData(), ip = request.headers.get("cf-connecting-ip") || "";
  fd.append("secret", env.TURNSTILE_SECRET); fd.append("response", String(body.turnstile).slice(0, 4096)); if (ip) fd.append("remoteip", ip);
  let ok = false;
  try { ok = !!(await (await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", { method: "POST", body: fd })).json()).success; } catch (e) {}
  return ok ? null : json({ need_turnstile: true, sitekey: env.TURNSTILE_SITEKEY || "", error: "The check did not pass: please try it again." }, 428);
}
const fromProgram = (request) => /^planetCompute\//.test(request.headers.get("user-agent") || "");
async function createUser(env, email) {
  for (let i = 0; i < 5; i++) {
    const id = newUserId(), t = iso();
    try {
      await ddb(env, "TransactWriteItems", { TransactItems: [
        { Put: { TableName: tableName(env), Item: M({ pk: `CANON#${canonEmail(email)}`, sk: "CANON", user_id: id, email, at: t }), ConditionExpression: "attribute_not_exists(pk)" } },
        { Put: { TableName: tableName(env), Item: M({ pk: `USER#${id}`, sk: "PROFILE", user_id: id, primary_email: email, created_at: t,
          status: "active", email_count: 1, device_count: 0, ulist_pk: "U#" + t.slice(0, 7), ulist_sk: `${t}#${id}` }),
          ConditionExpression: "attribute_not_exists(pk)" } },
        { Put: { TableName: tableName(env), Item: M({ pk: `EMAIL#${email}`, sk: "EMAIL", user_id: id, added_at: t, ...emailIndex(email) }),
          ConditionExpression: "attribute_not_exists(pk)" } },
        { Put: { TableName: tableName(env), Item: M({ pk: `USER#${id}`, sk: `EMAIL#${email}`, user_id: id, email, added_at: t, verified_at: t }) } },
      ] });
      await bumpStats(env, "users", 1);
      return id;
    } catch (e) {
      if (e.type !== "TransactionCanceledException") throw e;
      const existing = await userForEmail(env, email);       // someone signed up with this address at the same moment
      if (existing) return existing;
    }
  }
  throw new Error("could not create account");
}

const sessionHash = (env, token) => sha256hex(`${authSecret(env)}|session|${token}`);
// scope "worker" (security review W5): a sign-in for a server's program copies or test traffic, which can only do what
