// The token risk statement on My Balance (user 2026-10-30), under the crypto confirmation: once checked it stays checked
// (cannot be unchecked). One row per account in <prefix>token-risk-accepted (sk "ACCEPTED", written once, never changed),
// with the sentence as shown ([Token Name] = the coin(s) of the share set in force).
const tokenRiskTable = (env) => PFX(env) + "token-risk-accepted";
const TOKEN_RISK_TEXT = "I understand that [Token Name] is a ledger record only, may have no real value, and could lose 100% of any value it ever has. I accept it at my own discretion and risk.";
const tokenNames = (env) => ledgerAt(env, iso()).then((set) => set.filter((x) => x.coin).map((x) => x.coin.name).join(" and ")).catch(() => "") ;
async function tokenRisk(env, uid) {
  const [r, name] = await Promise.all([ddb(env, "GetItem", { TableName: tokenRiskTable(env), Key: M({ user_id: uid, sk: "ACCEPTED" }) }), tokenNames(env)]);
  const x = U(r.Item);
  return { accepted: !!x, at: x ? x.at : "", text: x ? x.text : TOKEN_RISK_TEXT.replace("[Token Name]", name || "PlanetComp") };
}
async function acceptTokenRisk(env, request, me, accepted) {
  if (accepted !== true) return json({ error: "This statement cannot be withdrawn once accepted: send accepted: true." }, 400);
  const at = iso(), prof = (await getItem(env, `USER#${me.user_id}`, "PROFILE")) || {}, ua = request.headers.get("user-agent") || "", name = (await tokenNames(env)) || "PlanetComp";
  try {
    await ddb(env, "PutItem", { TableName: tokenRiskTable(env), ConditionExpression: "attribute_not_exists(user_id)",
      Item: M({ user_id: me.user_id, sk: "ACCEPTED", at, accepted: true, token_name: name, text: TOKEN_RISK_TEXT.replace("[Token Name]", name),
        email: prof.primary_email || "", country: (request.cf && request.cf.country) || "", ip: (request.headers.get("cf-connecting-ip") || "").slice(0, 45),
        user_agent: short(ua, 200), via: /^planetCompute\//.test(ua) ? "program" : "website" }) });
  } catch (e) {
    if (e.type === "ConditionalCheckFailedException") return json({ ok: true, accepted: true, already: true, ...(await tokenRisk(env, me.user_id)) });
    throw e;
  }
  return json({ ok: true, accepted: true, at });
}
// Security review W6: a new payout address needs a code sent to the account's email (a stolen sign-in alone cannot
