  if (!ok32) return json({ error: "That is not a Solana wallet address (base58, 32 bytes). Enter the address only: never a key or recovery phrase." }, 400);
  const p = (await getItem(env, `USER#${userId}`, "PROFILE")) || {}, old = p.solana_address || "";
  if (old === a) return json({ error: "That is already your wallet address." }, 409);
  if (env.SOLANA_RPC_URL) {                               // a token account or a mint is not a wallet: coins sent there are lost
    try {
      const r = await solRpc(env.SOLANA_RPC_URL, "getAccountInfo", [a, { encoding: "base64", commitment: "confirmed" }]);
      const o = r && r.value && r.value.owner;
      if (o === TOKEN_PROGRAM || o === TOKEN_2022_PROGRAM) return json({ error: "That address is a token account or a coin's mint, not a wallet. Enter your wallet's own address." }, 400);
    } catch (e) {}
  }
