    const st = (await solRpc(env.SOLANA_RPC_URL, "getSignatureStatuses", [[sig]])).value[0];
    if (st && st.err) return { signature: sig, ok: false, error: JSON.stringify(st.err) };
    if (st && (st.confirmationStatus === "confirmed" || st.confirmationStatus === "finalized")) return { signature: sig, ok: true };
