    for (let i = 0; i < 20; i++) { info = await inspectDeposit(env, signature, tokenAccount); if (!info.pending) break; await new Promise((r) => setTimeout(r, 1500)); }
    if (info.pending) return json({ pending: true, message: "Not confirmed yet. Try again in a few seconds." }, 202);
    if (info.error) return json({ error: info.error }, 400);
    const b = await balanceItem(env, me.user_id);
    const fromLinked = b.wallet && info.authority === b.wallet, hasRef = info.accountKeys.includes(reference);
    if (!fromLinked && !hasRef) return json({ error: "That transaction is not from your linked wallet and does not carry your deposit reference." }, 403);
    if (info.received <= 0n) return json({ error: "That transaction did not send tokens to PlanetCompute." }, 400);
    const fresh = await creditDeposit(env, me.user_id, signature, info.received, hasRef ? "reference" : "linked-wallet");
