  const keep = rows.filter((r) => only === "fail" ? !r.pass : only === "pass" ? !!r.pass : true).sort((a, b) => (a.sk < b.sk ? 1 : -1)).slice(0, 1000);
  return { day, summary: sum, rows: keep.map((r) => ({ ...r, credited_wu: (r.credited_uwu || 0) / 1e6, bonus: (r.bonus_f15 || 0) / 1e15 })) };
