    const ab = appBuildOfUa(request.headers.get("user-agent"));
    await this.state.storage.put("who", { user, device, net, app: !!ab, build_time: ab ? ab.build_time : 0 });
    try { await this.groupStub(net).fetch("https://police.internal/join", { method: "POST", body: JSON.stringify({ name: `police:${user}:${device}` }) }); }
    catch (e) { await this.state.storage.setAlarm(Date.now() + 3000); }   // no group: test on our own
