    const P = (await this.state.storage.get("providers")) || {};
    if (!this.waiting) this.waiting = new Map();
    if (!this.busy) this.busy = new Map();
    if (!this.queue) this.queue = [];                                   // jobs waiting for a free computer, oldest first
