    if (path === "/grid/leave") { const b = await request.json(); delete P[b.name]; await this.state.storage.put("providers", P); return reply({ ok: true }); }
    if (path === "/grid/providers") return reply({ queued: this.queue.length, providers: Object.entries(P).map(([n, p]) => ({ device: p.device, user: p.user, models: p.models, busy: this.busy.get(n) || 0, since: new Date(p.at).toISOString() })) });
