function simplePage(title, heading, body, top) {
  return `<!doctype html><html lang="en"><head>${HEAD}<title>${title}</title>
<style>
body { min-height: 100vh; display: grid; place-items: center; text-align: center; padding: 16px;
  background: radial-gradient(700px 500px at 50% 0%, rgba(56, 217, 245,.12), transparent 60%), var(--bg); }
.box { max-width: 560px; }
.box img { width: 150px; height: 150px; margin-bottom: 16px; }
.box p { color: var(--muted); }
.row { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 22px; }
</style>${top ? `<style>body { display: block; padding: 0; } .box { margin: 28px auto 40px; padding: 0 16px; }</style>` : ""}</head><body>${top || ""}<div class="box">
${globeLogo(150)}
<h1 style="font-size:2rem">${heading}</h1>${body}
</div></body></html>`;
}

