// ---------------------------------------------------------------------------
// The PlanetCompute model library, for the planetCompute program (Harness). The files are kept in a private
// Backblaze B2 bucket (planetcompute-ai/Models/) and ALWAYS reach users through Cloudflare (this Worker): B2 does
// not charge for traffic to Cloudflare, and the B2 key never leaves Cloudflare.
//   GET /api/models                 the library (Models/catalog.json), public, cached 10 minutes
//   GET /api/models/file/<id>       one model file, streamed, signed-in users only; Range requests (resume) pass
// Needs the secrets B2_MODELS_KEY_ID and B2_MODELS_APP_KEY (2026-10-21: set to the existing account key at the user's
// request; to be replaced by a key limited to that bucket and Models/, read and list only). This code only ever
// reads Models/. Without them both answer 503 and the program downloads from the models' publishers instead.
let b2Models = null;
async function b2ModelsAuth(env) {
  if (!env.B2_MODELS_KEY_ID || !env.B2_MODELS_APP_KEY) return null;
  if (b2Models && b2Models.until > now()) return b2Models;
  const a = await (await fetch("https://api.backblazeb2.com/b2api/v3/b2_authorize_account",
    { headers: { authorization: "Basic " + btoa(env.B2_MODELS_KEY_ID + ":" + env.B2_MODELS_APP_KEY) } })).json();
  const api = a.apiInfo && a.apiInfo.storageApi;
  // a key limited to one bucket names it; an account-wide key does not: then the library bucket is planetcompute-ai
  const bucket = api && api.allowed && api.allowed.buckets && api.allowed.buckets[0];
  const name = (bucket && bucket.name) || env.B2_MODELS_BUCKET || "planetcompute-ai";
  if (!a.authorizationToken || !api) return null;
  b2Models = { token: a.authorizationToken, base: `${api.downloadUrl}/file/${name}`, until: now() + 20 * 3600 };
  return b2Models;
}
// Models/catalog.json = the originals (what the released program reads); Models/catalog-editions.json = every library
// file with its PlanetCompute edition where one exists (planetCompute-CPP/scripts/models_editions.py), read by programs
// that ask /api/models?all=1. Without the editions catalog, all=1 falls back to the originals.
const modelCatalogs = {};
async function modelLibrary(env, editions) {
  const name = editions ? "catalog-editions.json" : "catalog.json";
  const c = modelCatalogs[name];
  if (c && c.until > now()) return c.data;
  const b = await b2ModelsAuth(env);
  if (!b) return null;
  const r = await fetch(`${b.base}/Models/${name}`, { headers: { authorization: b.token } });
  if (!r.ok) return editions ? modelLibrary(env, false) : null;
  const data = await r.json();
  modelCatalogs[name] = { data, until: now() + 600 };
  return data;
}
async function handleModels(request, env, url) {
  try {
    if (url.pathname === "/api/models") {
      const lib = await modelLibrary(env, url.searchParams.get("all") === "1");
      return lib ? json({ models: (lib.models || []).map((m) => agreementOf(m) ? { ...m, agreement: agreementOf(m) } : m) })
        : json({ error: "The model library is not switched on." }, 503);
    }
    if (url.pathname === "/api/models/agreement") {
      const who = await currentUser(env, request);
      if (!who) return json({ error: "Not signed in." }, 401);
      const model = await libraryModel(env, url.searchParams.get("id"));
      if (!model) return json({ error: "No such model." }, 404);
      const a = agreementOf(model);
      return json({ id: model.id, required: !!a, accepted: a ? await hasAcceptedLicence(env, who.user_id, model) : true, agreement: a });
    }
    const m = url.pathname.match(/^\/api\/models\/file\/([a-z0-9][a-z0-9._-]{0,80})$/);
    if (!m) return json({ error: "Not found." }, 404);
    if (!(await currentUser(env, request))) return json({ error: "Not signed in." }, 401);
    // ?edition=1: the PlanetCompute edition (programs that read the editions catalog); otherwise the original
    const ed = url.searchParams.get("edition") === "1";
    const lib = await modelLibrary(env, ed), b = await b2ModelsAuth(env);
    if (!lib || !b) return json({ error: "The model library is not switched on." }, 503);
    const model = (lib.models || []).find((x) => x.id === m[1]);
    if (!model) return json({ error: "No such model." }, 404);
    if (agreementOf(model) && !(await hasAcceptedLicence(env, (await currentUser(env, request)).user_id, model)))
      return json({ error: "This model's licence needs your agreement first.", needs_agreement: true, agreement: agreementOf(model) }, 403);
    const h = { authorization: b.token };
    if (request.headers.get("range")) h.range = request.headers.get("range");
    const r = await fetch(`${b.base}/Models/${encodeURIComponent(model.id)}/${encodeURIComponent(ed && model.b2_file ? model.b2_file : model.file)}`, { headers: h });
    if (!r.ok && r.status !== 206) return json({ error: "The file is not available right now." }, 502);
    const out = new Headers({ "content-type": "application/octet-stream", "cache-control": "no-store",
      "content-disposition": `attachment; filename="${model.file}"` });
    for (const k of ["content-length", "content-range", "accept-ranges"]) if (r.headers.get(k)) out.set(k, r.headers.get(k));
    return new Response(r.body, { status: r.status, headers: out });
  } catch (e) {
    console.log("models", e && e.message);
    return json({ error: "The model library is not available right now." }, 503);
  }
}

// ---------------------------------------------------------------------------
// Licence agreements. Most library models are Apache 2.0 / MIT / OpenMDW: no agreement. The licences below pass their
// use rules on to every user in an agreement (LTX 3.1, Llama, Stability, OpenRAIL++), so the program asks the user to
// accept before the first download, and this site gives such a model's files only to accounts that accepted.
// A library entry names its licence with "agreement": "<key>" (models/catalog.json); the admin Models tab uses the
// table's licence id. Each acceptance is one item in <prefix>model-agreements (see CreateTables.py):
//   user_id / sk "<model_id>#<licence>#<version>": email, model_id, model_name, licence, licence_title, licence_version,
//   licence_url, accepted (true), accepted_at, ip, country, city, user_agent, via; index by-model (model_id / accepted_at).
// A new licence version (change "version") asks every user again.
const LICENCE_AGREEMENTS = {
  "llama3.3": { title: "Llama 3.3 Community License", version: "2024-12-06", url: "https://www.llama.com/llama3_3/license/",
    policy: "https://www.llama.com/llama3_3/use-policy/",
    points: ["Free to use, change and share; a separate licence from Meta is needed above 700 million monthly users.",
      "You agree to Meta's Acceptable Use Policy (no illegal, harmful or deceptive uses).",
      "Built with Llama: a changed model you share must keep the licence and a name beginning with \"Llama\"."] },
  "ltx-2.x-community": { title: "LTX-2.x Community License", version: "2026-08-11", url: "https://github.com/Lightricks/LTX-2/blob/main/LICENSE-2_x",
    policy: "https://static.lightricks.com/legal/ltx-acceptable-use-policy.pdf",
    points: ["Free only if your organisation (with its affiliates) earns under US$10 million a year; above that you need a paid licence from Lightricks (licensing@ltx.io) before any use.",
      "You agree to the use restrictions (Attachment A) and Lightricks' Acceptable Use Policy: no illegal or harmful uses, no deepfakes of people without their consent.",
      "Content you share must be clearly labelled as machine-generated; do not remove watermarks or other AI-disclosure features.",
      "Changed or fine-tuned versions may be shared only under this same licence, with a copy of it."] },
  "stabilityai-ai-community": { title: "Stability AI Community License", version: "2024-07-05", url: "https://stability.ai/community-license-agreement",
    policy: "https://stability.ai/use-policy",
    points: ["Free for research, personal use and organisations earning under US$1 million a year; above that an enterprise licence from Stability AI is needed.",
      "You agree to Stability AI's Acceptable Use Policy.",
      "Show \"Powered by Stability AI\" when you share products built with it, and keep the licence with any copy."] },
  "stable-audio-community": { title: "Stability AI Community License", version: "2024-07-05", url: "https://huggingface.co/stabilityai/stable-audio-open-1.0/blob/main/LICENSE.md",
    policy: "https://stability.ai/use-policy",
    points: ["Free for research, personal use and organisations earning under US$1 million a year; above that an enterprise licence from Stability AI is needed.",
      "You agree to Stability AI's Acceptable Use Policy.",
      "Show \"Powered by Stability AI\" when you share products built with it, and keep the licence with any copy."] },
  "openrail++": { title: "CreativeML Open RAIL++-M License", version: "2023-07-26", url: "https://huggingface.co/stabilityai/stable-diffusion-xl-base-1.0/blob/main/LICENSE.md",
    points: ["Free to use, change and share, including commercially.",
      "You agree to the use-based restrictions in Attachment A (no illegal, harmful, deceptive or discriminatory uses).",
      "Anyone you share it or a changed version with must get the same restrictions."] },
};
const agreementsTable = (env) => PFX(env) + "model-agreements";
function agreementOf(model) {
  const k = model && (model.agreement && typeof model.agreement === "object" ? model.agreement.key : model.agreement);
  const a = k && LICENCE_AGREEMENTS[k];
  return a ? { key: k, ...a } : null;
}
const agreementSk = (id, a) => `${id}#${a.key}#${a.version}`;
async function libraryModel(env, id) {
  for (const ed of [true, false]) {
    const lib = await modelLibrary(env, ed);
    const m = lib && (lib.models || []).find((x) => x.id === id);
    if (m) return m;
  }
  return null;
}
async function hasAcceptedLicence(env, uid, model) {
  const a = agreementOf(model);
  if (!a) return true;
  const g = await ddb(env, "GetItem", { TableName: agreementsTable(env), Key: M({ user_id: uid, sk: agreementSk(model.id, a) }), ConsistentRead: true });
  return !!(g.Item && g.Item.accepted && g.Item.accepted.BOOL);
}
// POST /api/models/accept {model_id, via?}: the signed-in user accepts the model's licence. Saved for the model and
// for each part it needs under the same licence (an LTX model's text encoder and VAEs). Answers {accepted, agreement}.
async function acceptModelLicence(request, env, who, body) {
  const model = await libraryModel(env, String(body.model_id || "").slice(0, 80));
  if (!model) return json({ error: "No such model." }, 404);
  const a = agreementOf(model);
  if (!a) return json({ accepted: true, required: false });
  const lib = (await modelLibrary(env, true)) || (await modelLibrary(env, false)) || { models: [] };
  const parts = (model.needs || []).map((n) => (lib.models || []).find((x) => x.id === n)).filter((x) => x && agreementOf(x) && agreementOf(x).key === a.key);
  const p = await profile(env, who.user_id).catch(() => null), t = iso(), cf = request.cf || {};
  for (const m of [model, ...parts]) {
    await ddb(env, "PutItem", { TableName: agreementsTable(env), Item: M({ user_id: who.user_id, sk: agreementSk(m.id, a),
      email: p ? p.primary_email || "" : "", model_id: m.id, model_name: m.name || m.id, licence: a.key, licence_title: a.title,
      licence_version: a.version, licence_url: a.url, accepted: true, accepted_at: t,
      ip: (request.headers.get("cf-connecting-ip") || "").slice(0, 45), country: cf.country || "", city: cf.city || "",
      user_agent: (request.headers.get("user-agent") || "").slice(0, 300), via: String(body.via || "planetCompute program").slice(0, 60) }) });
  }
  // a copy for the user, sent at once (user's rule): what was accepted, when, from where; email_sent_at notes it was sent
  let emailed = false;
  if (p && p.primary_email) {
    const ip = (request.headers.get("cf-connecting-ip") || "").slice(0, 45), where = [cf.city, cf.country].filter(Boolean).join(", ");
    const lines = [`You accepted the ${a.title} (version ${a.version}) for ${model.name || model.id} on planetCompute.`, "",
      `Model: ${model.name || model.id} (${model.id})${parts.length ? "; also its parts " + parts.map((x) => x.id).join(", ") : ""}`,
      `Accepted: ${t} (UTC)`, `From: IP address ${ip}${where ? " (" + where + ")" : ""}`, "", "What you agreed to:",
      ...a.points.map((x) => "- " + x), "", `Full licence: ${a.url}`, ...(a.policy ? [`Acceptable use policy: ${a.policy}`] : []), "",
      "If this was not you, reply to this email or write to us through planetcompute.ai."];
    const html = `<p>${lines.slice(0, 1).map(escHtml).join("")}</p><p>${lines.slice(2, 5).map(escHtml).join("<br>")}</p><p><b>What you agreed to:</b></p><ul>${a.points.map((x) => "<li>" + escHtml(x) + "</li>").join("")}</ul>` +
      `<p>Full licence: <a href="${escHtml(a.url)}">${escHtml(a.url)}</a>${a.policy ? `<br>Acceptable use policy: <a href="${escHtml(a.policy)}">${escHtml(a.policy)}</a>` : ""}</p>` +
      `<p style="color:#666">If this was not you, reply to this email or write to us through planetcompute.ai.</p>`;
    try {
      await sendEmail(env, { to: [p.primary_email], subject: `You accepted the ${a.title} for ${model.name || model.id} (planetCompute)`, text: lines.join("\n"), html });
      emailed = true;
      await ddb(env, "UpdateItem", { TableName: agreementsTable(env), Key: M({ user_id: who.user_id, sk: agreementSk(model.id, a) }),
        UpdateExpression: "SET email_sent_at = :e", ExpressionAttributeValues: { ":e": S_(iso()) } });
    } catch (e) { console.log("agreement email", e && e.message); }
  }
  return json({ accepted: true, required: true, accepted_at: t, emailed, agreement: a, models: [model.id, ...parts.map((x) => x.id)] });
}

// ---------------------------------------------------------------------------
// /temp/ : files the team shares for a while (pictures from tests, ...), kept in B2 under TEMP/ and always served
// through Cloudflare. Read only, TEMP/ only. TEMP/index.json lists them: {files: [{name, title?, note?}]}; names
// are letters, digits, dot, dash and underscore. Uses the model library's B2 key (b2ModelsAuth).
const TEMP_TYPES = { png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", webp: "image/webp", gif: "image/gif",
  mp4: "video/mp4", webm: "video/webm", avi: "video/x-msvideo", txt: "text/plain; charset=utf-8", json: "application/json" };
// The planetCompute program for each system, as published to B2 (client/LATEST.json, scripts/publish_client.py):
// /download is a page with the four buttons, /download/<system> streams the file through Cloudflare (B2 does not
// charge for traffic to Cloudflare). The B2 key never leaves this Worker.
const DOWNLOADS = {
  windows: { key: "windows-x86_64", name: "planetCompute.exe", label: "Windows", note: "Windows 10 or 11, 64-bit. Uses any graphics card (NVIDIA, AMD, Intel) through Vulkan, and runs on the processor alone on a PC without one." },
  mac: { key: "macos-aarch64", name: "planetCompute", label: "Mac", note: "Apple silicon (M1 or newer). Uses the Mac's GPU (Metal)." },
  linux: { key: "linux-x86_64", name: "planetCompute", label: "Linux", note: "64-bit (x86_64), Ubuntu 22.04 or newer. The processor; needs libwebkit2gtk-4.1 for the window (or start it with --headless)." },
  "linux-vulkan": { key: "linux-x86_64-vulkan", name: "planetCompute", label: "Linux with a GPU", note: "As Linux, plus the graphics card through Vulkan (needs libvulkan1 and the GPU driver)." },
  "linux-server": { key: "linux-x86_64-server", name: "planetCompute", label: "Linux server (no window)", note: "64-bit (x86_64) servers: always headless, needs no desktop libraries. Run with --headless." },
};
async function handleDownload(request, env, url, which) {
  const b = await b2ModelsAuth(env).catch(() => null);
  const latest = b ? await fetch(`${b.base}/client/LATEST.json`, { headers: { authorization: b.token } }).then((r) => r.ok ? r.json() : null).catch(() => null) : null;
  const build = (k) => latest && latest.builds && latest.builds[DOWNLOADS[k].key];
  if (which === "latest.json") {
    if (!latest) return json({ error: "Not available right now." }, 503);
    const builds = {};
    // sig: Ed25519 of "planetCompute release|<sha256>" by the release key (kept offline); the servers' agents refuse a build without it
    // commit + build_time per build (each platform can be a different build; plan_old_programs #3: the programs compare
    // their own build time with it), and the site's minimum for earning (MIN_EARN_BUILD / MIN_EARN_MODE)
    for (const k of Object.keys(DOWNLOADS)) { const f = build(k); if (f) builds[k] = { sha256: f.sha256, bytes: f.bytes, url: `/download/${k}`, ...(f.sig ? { sig: f.sig } : {}), ...(f.sig2 ? { sig2: f.sig2 } : {}),
      ...(f.build_time ? { commit: String(f.commit || ""), build_time: Number(f.build_time) } : {}) }; }
    const me = minEarn(env);
    return new Response(JSON.stringify({ version: latest.version, commit: latest.commit || "", builds, ...(me.min ? { min_earn_build: me.min, min_earn_mode: me.mode } : {}) }),
      { headers: { "content-type": "application/json", "cache-control": "no-store" } });
  }
  if (which) {
    const d = DOWNLOADS[which], f = build(which);
    if (!d || !f || !/^[A-Za-z0-9._-]{1,120}$/.test(f.file)) return html(NOT_FOUND, 404);
    if (request.method !== "GET" && request.method !== "HEAD") return new Response("GET only", { status: 405 });
    const r = await fetch(`${b.base}/client/${encodeURIComponent(latest.version)}/${encodeURIComponent(f.file)}`, { headers: { authorization: b.token } });
    if (!r.ok) return new Response("Not available right now. Please try again in a minute.", { status: 503 });
    const h = new Headers({ "content-type": "application/octet-stream", "content-disposition": `attachment; filename="${d.name}"`,
      "cache-control": "no-store", "x-content-type-options": "nosniff" });
    if (r.headers.get("content-length")) h.set("content-length", r.headers.get("content-length"));
    return new Response(request.method === "HEAD" ? null : r.body, { status: 200, headers: h });
  }
  const esc = (t) => String(t || "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  const cards = Object.keys(DOWNLOADS).map((k) => {
    const d = DOWNLOADS[k], f = build(k);
    return `<div class="dl"><h2>${d.label}</h2><p>${esc(d.note)}</p>` + (f
      ? `<a class="btn btn-gold" href="/download/${k}">Download for ${d.label}</a><small>${(f.bytes / 1e6).toFixed(0)} MB · version ${esc(latest.version)} · SHA-256 <code>${esc(f.sha256)}</code>${f.sig ? ` · <span title="Ed25519 signature of 'planetCompute release|&lt;SHA-256&gt;' by PlanetCompute's release key (public key ${RELEASE_PUBKEY}): ${esc(f.sig)}">signed</span>` : ""}</small>`
      : `<p><b>Not available right now.</b></p>`) + `</div>`;
  }).join("");
  return html(simplePage("Download planetCompute · PlanetCompute", "Website may not activate all features, to get all features, Download our client app for Windows, Mac or Linux.",
    `<style>.box h1{font-size:1.4rem!important;line-height:1.35}.dl{text-align:left;margin:14px 0;padding:16px 18px;border-radius:7px;border:1px solid var(--border);background:var(--surface)}.dl h2{margin:0 0 4px;font-size:1.15rem}.dl p{margin:0 0 10px}.dl small{display:block;margin-top:8px;color:var(--muted);word-break:break-all}.dl code{font-size:.78rem}</style>
<p>One program: share compute, and receive compute: make pictures, video and chat on your own computer, privately and free. Sign in with the same account as here.</p>${cards}
<p style="font-size:.88rem">The programs are not code-signed yet: Windows may say "Windows protected your PC" (More info, then Run anyway); on a Mac, Control-click the file and choose Open; on Linux, make it executable first (<code>chmod +x planetCompute</code>).</p>`, topBar("")));
}

async function handleTemp(request, env, url) {
  if (request.method !== "GET" && request.method !== "HEAD") return new Response("GET only", { status: 405 });
  const b = await b2ModelsAuth(env).catch(() => null);
  if (!b) return new Response("Not available right now.", { status: 503 });
  const name = url.pathname.replace(/^\/temp\/?/, "");
  if (!name) {
    const r = await fetch(`${b.base}/TEMP/index.json`, { headers: { authorization: b.token } });
    const list = r.ok ? ((await r.json()).files || []) : [];
    const esc = (t) => String(t || "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
    const items = list.filter((f) => /^[A-Za-z0-9._-]{1,120}$/.test(f.name)).map((f) => {
      const ext = f.name.split(".").pop().toLowerCase(), src = "/temp/" + encodeURIComponent(f.name);
      const media = /^(mp4|webm)$/.test(ext) ? `<video src="${src}" controls preload="metadata"></video>`
        : /^(png|jpe?g|webp|gif)$/.test(ext) ? `<a href="${src}"><img src="${src}" alt="${esc(f.title || f.name)}" loading="lazy"></a>` : `<a href="${src}">${esc(f.name)}</a>`;
      return `<figure>${media}<figcaption><b>${esc(f.title || f.name)}</b>${f.note ? "<br>" + esc(f.note) : ""}</figcaption></figure>`;
    }).join("");
    return new Response(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex"><title>PlanetCompute shared files</title><style>
:root{color-scheme:light dark;--bg:#071422;--fg:#e8f3fb;--mut:#93a9bb;--line:#1d3247}@media (prefers-color-scheme:light){:root{--bg:#f4f8fb;--fg:#0c1b2a;--mut:#4d6274;--line:#d5e0e9}}
body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.5 system-ui,sans-serif;padding:16px}h1{font-size:20px;margin:4px 0 2px}p{color:var(--mut);margin:0 0 16px}
main{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:14px}figure{margin:0;border:1px solid var(--line);border-radius:12px;padding:10px}
img,video{width:100%;border-radius:8px;display:block;background:#0003}figcaption{font-size:13px;color:var(--mut);margin-top:6px;word-break:break-word}figcaption b{color:var(--fg)}
</style></head><body><h1>PlanetCompute shared files</h1><p>${list.length} file${list.length === 1 ? "" : "s"} · kept for a while, then removed</p><main>${items || "<p>Nothing here.</p>"}</main></body></html>`,
      { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "x-robots-tag": "noindex" } });
  }
  if (!/^[A-Za-z0-9._-]{1,120}$/.test(name) || name === "index.json") return new Response("Not found", { status: 404 });
  const r = await fetch(`${b.base}/TEMP/${encodeURIComponent(name)}`, { headers: { authorization: b.token, ...(request.headers.get("range") ? { range: request.headers.get("range") } : {}) } });
  if (!r.ok && r.status !== 206) return new Response("Not found", { status: 404 });
  const h = new Headers({ "content-type": TEMP_TYPES[name.split(".").pop().toLowerCase()] || "application/octet-stream",
    "cache-control": "public, max-age=300", "x-robots-tag": "noindex", "x-content-type-options": "nosniff" });
  for (const k of ["content-length", "content-range", "accept-ranges"]) if (r.headers.get(k)) h.set(k, r.headers.get(k));
  return new Response(request.method === "HEAD" ? null : r.body, { status: r.status, headers: h });
}


