const MY_HOST = "my.planetcompute.ai", MY_ORIGIN = "https://" + MY_HOST, MY_V = "v1";
const myBucket = (env) => String(env.B2_MEDIA_BUCKET_NAME || "planetcompute-user-media").trim();
