      const r = await fetch(up.uploadUrl, { method: "POST", body, headers: { authorization: up.authorizationToken, "Content-Length": String(x.bytes),
        "X-Bz-File-Name": encodeURIComponent(`${x.tok}/${n}`), "Content-Type": UPLOAD_TYPES[ext], "X-Bz-Content-Sha1": "do_not_verify",
        "X-Bz-Info-b2-cache-control": encodeURIComponent(MY_IMMUTABLE) } });
