  const pm = myPoolDetails(x.made);                     // a pool picture: from the registry (poolMadeBy), never from the program
  const meta = { kind, made_with: "planetCompute.cpp", ai_generated: true, generated_on: x.via === "browser" ? "the PlanetCompute pool using Browser (Express mode)" : pm ? "the PlanetCompute pool" : "the user's own computer using Client", shared: new Date(x.at || Date.now()).toISOString(),
    ...(pm || {}),
    bytes: x.bytes || 0, ...(int(m.width) && int(m.height) ? { width: int(m.width), height: int(m.height) } : {}),
    ...(typeof m.model_name === "string" && m.model_name ? { model: m.model_name.slice(0, 80) } : {}), link: `${MY_ORIGIN}/${x.tok}` };
  const g = await ddb(env, "GetItem", { TableName: tableName(env), Key: { pk: { S: `UPLOAD#${x.uid}/${x.name}` }, sk: { S: "VIEWS" } } }).catch(() => ({}));
  const views = g.Item && g.Item.views ? +g.Item.views.N : 0;
  await put(`${x.tok}/meta.json`, JSON.stringify(meta), "application/json");
  await put(`${x.tok}/views.json`, JSON.stringify({ views, at: iso() }), "application/json", "public, max-age=600");
  await put(`${x.tok}/index.html`, myPage({ tok: x.tok, kind, show, at: x.at || Date.now(), bytes: x.bytes, w: meta.width, h: meta.height, model: meta.model, views, via: x.via, pool: pm }),
    "text/html; charset=utf-8", "public, max-age=31536000");
  names.push("meta.json", "views.json");
  await ddb(env, "UpdateItem", { TableName: tableName(env), Key: { pk: { S: `UPLOAD#${x.uid}/${x.name}` }, sk: { S: "VIEWS" } },
    UpdateExpression: "SET #m = :one", ExpressionAttributeNames: { "#m": "my" }, ExpressionAttributeValues: { ":one": { N: "1" } } }).catch(() => {});
  await myPurge(env, x.tok, names);
