// ---------------------------------------------------------------------------
// My content (planetcompute.ai/mycontent): the signed-in user's saved files. Trash = B2 public/users_trash/<user_id>/
// (a copy, then every version of the original deleted); trash older than 30 days is removed when the list is read.
//   GET  /api/mycontent                     {files, trash, used, quota}
//   POST /api/mycontent/trash   {name}      move to the trash (the link stops working)
//   POST /api/mycontent/restore {name}      back from the trash (the link works again)
//   POST /api/mycontent/delete  {name}      delete from the trash for good
//   POST /api/mycontent/empty               empty the trash
const UPLOAD_QUOTA = 2 * 1024 * 1024 * 1024;               // 2 GB per account (files, not the trash)
const TRASH_DAYS = 30;
async function b2Call(b, name, body) {
  const r = await fetch(`${b.api}/b2api/v3/${name}`, { method: "POST", headers: { authorization: b.token }, body: JSON.stringify(body) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) { if (r.status === 401) b2Writer = null; throw new Error(j.message || name + " failed"); }
  return j;
}
async function b2List(b, prefix) {                          // every file directly in prefix (not in sub-folders)
  const out = []; let start = null;
  do {
    const j = await b2Call(b, "b2_list_file_names", { bucketId: b.bucketId, prefix, delimiter: "/", maxFileCount: 1000, ...(start ? { startFileName: start } : {}) });
    for (const f of j.files || []) if (f.action === "upload") out.push(f);
    start = j.nextFileName;
  } while (start);
  return out;
}
async function b2Remove(b, fileName) {                      // every version of one file
  const j = await b2Call(b, "b2_list_file_versions", { bucketId: b.bucketId, prefix: fileName, maxFileCount: 100 });
  for (const f of (j.files || []).filter((f) => f.fileName === fileName)) await b2Call(b, "b2_delete_file_version", { fileName: f.fileName, fileId: f.fileId });
}
async function b2Move(b, from, to) {
  const f = (await b2Call(b, "b2_list_file_names", { bucketId: b.bucketId, prefix: from, maxFileCount: 1 })).files || [];
  if (!f.length || f[0].fileName !== from) return false;
  await b2Call(b, "b2_copy_file", { sourceFileId: f[0].fileId, fileName: to });
  await b2Remove(b, from);
  return true;
}
async function uploadViewCounts(env, uid, names) {
  const out = {};
  for (let i = 0; i < names.length; i += 100) {
    const keys = names.slice(i, i + 100).map((n) => ({ pk: { S: `UPLOAD#${uid}/${n}` }, sk: { S: "VIEWS" } }));
    const r = await ddb(env, "BatchGetItem", { RequestItems: { [tableName(env)]: { Keys: keys } } }).catch(() => ({}));
    for (const it of ((r.Responses || {})[tableName(env)] || []))
      out[it.pk.S.split("/").slice(1).join("/")] = { views: it.views ? +it.views.N : 0, share: it.share ? it.share.S : "", my: !!it.my };
  }
  return out;
}
async function uploadsUsed(b, uid) {
  return (await b2List(b, `public/users_uploads/${uid}/`)).reduce((n, f) => n + f.contentLength, 0);
}
async function handleMyContent(env, request, url, me, body) {
  const b = await b2WriteAuth(env).catch(() => null);
  if (!b) return json({ error: "Your content is not available right now." }, 503);
  const uid = me.user_id, live = `public/users_uploads/${uid}/`, bin = `public/users_trash/${uid}/`;
  const what = url.pathname.slice("/api/mycontent".length);
  if (what === "" && request.method === "GET") {
    const files = await b2List(b, live), trash = await b2List(b, bin), cut = Date.now() - TRASH_DAYS * 86400e3;
    for (const f of trash.filter((f) => f.uploadTimestamp < cut)) { await b2Remove(b, f.fileName).catch(() => {}); await shareForget(env, uid, f.fileName.slice(bin.length)); }
    const views = await uploadViewCounts(env, uid, files.map((f) => f.fileName.slice(live.length)));
    for (const f of files) {                     // files saved before share links: give them one now
      const n = f.fileName.slice(live.length);
      if (!(views[n] && views[n].share)) views[n] = { views: (views[n] || {}).views || 0, share: await shareToken(env, uid, n).catch(() => "") };
    }
    const row = (f, p) => { const name = f.fileName.slice(p.length), v = views[name] || {};
      return { name, bytes: f.contentLength, at: f.uploadTimestamp, views: v.views || 0, type: UPLOAD_TYPES[name.split(".").pop().toLowerCase()] || "",
        url: v.share ? myLink(url.origin, v.share, v.my) : undefined }; };
    return json({ files: files.map((f) => row(f, live)), trash: trash.filter((f) => f.uploadTimestamp >= cut).map((f) => ({ ...row(f, bin), url: undefined, views: undefined })),
      used: files.reduce((n, f) => n + f.contentLength, 0), quota: UPLOAD_QUOTA, trash_days: TRASH_DAYS });
  }
  if (request.method !== "POST") return json({ error: "POST only." }, 405);
  if (what === "/empty") { for (const f of await b2List(b, bin)) { await b2Remove(b, f.fileName); await shareForget(env, uid, f.fileName.slice(bin.length)); } return json({ ok: true }); }
  const name = uploadName(String(body.name || ""));
  if (!name) return json({ error: "No such file." }, 400);
  if (what === "/trash") {
    if (!(await b2Move(b, live + name, bin + name))) return json({ error: "No such file." }, 404);
    await myUnpublish(env, await myTokenOf(env, uid, name), uid, name, false).catch(() => {});   // the my. link stops too
    return json({ ok: true });
  }
  if (what === "/restore") {
    const f = (await b2List(b, bin)).find((x) => x.fileName === bin + name);
    if (!f) return json({ error: "No such file in the trash." }, 404);
    if ((await uploadsUsed(b, uid)) + f.contentLength > UPLOAD_QUOTA) return json({ error: "Not enough room: your files would be over 2 GB." }, 413);
    if (!(await b2Move(b, bin + name, live + name))) return json({ error: "No such file in the trash." }, 404);
    const tok = await myTokenOf(env, uid, name);
    if (tok) await myPublish(env, { tok, uid, name }).catch(() => {});   // the my. link works again
    return json({ ok: true });
  }
  if (what === "/delete") { await b2Remove(b, bin + name); await shareForget(env, uid, name); return json({ ok: true }); }
  return json({ error: "Not found." }, 404);
}

