  await ddb(env, "UpdateItem", { TableName: serversTable(env), Key: M({ server_id: sv.server_id, sk: "SERVER" }),
    UpdateExpression: "SET " + sets.join(", "), ConditionExpression: "attribute_exists(server_id)",
    ExpressionAttributeNames: names, ExpressionAttributeValues: M(vals) }).catch(() => {});
  hbServersMemo = null;
