  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(HB_KEYS_PHASE === 1 ? env.HB_SERVER_SECRET : await serverKey(env, "hb")), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
