  ssh_user: (v) => /^[a-z_][a-z0-9_-]{0,31}$/.test(v), ssh_port: (v) => v === "" || (/^\d{1,5}$/.test(v) && +v > 0 && +v < 65536),
  ssh_key_name: (v) => /^[\w.-]{1,80}$/.test(v),
  root_dir: (v) => v === "" || /^\/[\w./-]{1,200}$/.test(v),
  port_base: (v) => v === "" || (/^\d{4,5}$/.test(v) && +v >= 1024 && +v <= 65000),   // copy N on port port_base + N (empty = 7530)
  instances: (v) => /^[1-6]$/.test(v), cores: (v) => v === "" || (/^\d{1,3}$/.test(v) && +v <= 256), cap: (v) => v === "" || (/^\d{2,3}$/.test(v) && +v >= 10 && +v <= 100),
  account_email: (v) => /^[^\s@]{1,64}@[^\s@]{1,190}\.[a-z]{2,}$/i.test(v),
  provider: (v) => /^[\w .-]{0,40}$/.test(v), notes: (v) => v.length <= 300,
  role: (v) => v === "" || v === "sherpahub",            // sherpahub: its copies run as SherpaHubs (admin tab SherpaHubs), up to 5
