    await ddb(env, "UpdateItem", { TableName: workhorsesTable(env), Key: M({ server_id: id, sk: "SERVER" }),
      UpdateExpression: "SET session_issued_at = :t", ExpressionAttributeValues: M({ ":t": iso() }) });
