    port: Number(x.port) || 0, since: one(x.since, 30), restarts: Number(x.restarts) || 0, last_exit: one(x.last_exit, 60), device: one(x.device, 12),
    // the copy's models: [id, percent (100 = ready), error?]; null = it did not answer
