async function emailBugReporter(env, me, adminEmail, body) {
  const id = String(body.bug_id || "");
  if (!/^[0-9a-f]{10}$/.test(id)) return json({ error: "Bad report ID." }, 400);
  const old = await getBug(env, id);
  if (!old) return json({ error: "No such report." }, 404);
  if (!old.email) return json({ error: "This report has no email address." }, 400);
  const subject = String(body.subject || "").replace(/[\r\n\t\u0000-\u001f]+/g, " ").trim().slice(0, 150) || `Your bug report ${id}: ${old.subject}`;
  const message = String(body.message || "").replace(/\r/g, "").trim();
  if (message.length < 2 || message.length > 6000) return json({ error: "Write the message (up to 6,000 characters)." }, 400);
  const text = `${message}\n\n--\nAbout your bug report ${id} on planetcompute.ai: "${old.subject}"\nReply to this email to answer us.`;
  const html = `<div style="font-family:Arial,sans-serif;max-width:640px;color:#14182b"><div style="white-space:pre-wrap">${escHtml(message)}</div>` +
    `<p style="color:#667;font-size:13px;border-top:1px solid #dde;padding-top:10px;margin-top:18px">About your bug report ${escHtml(id)} on planetcompute.ai: ` +
    `"${escHtml(old.subject)}". Reply to this email to answer us.</p></div>`;
  if (!env.CONTACT_DRY_RUN) {
    try { await sendEmail(env, { to: [old.email], subject, text, html, replyTo: adminEmail || undefined }); }
    catch (e) { console.log("bug reply mail", e.message); return json({ error: "The email could not be sent: " + e.message.slice(0, 200) }, 502); }
  }
  const entry = { at: iso(), by: me.user_id, by_email: adminEmail, kind: "email", to: old.email, subject, text: message };
  try { return json({ ok: true, sent_to: old.email, bug: bugRow(await saveBugLog(env, id, old, [entry], "")) }); }
  catch (e) { return json({ ok: true, sent_to: old.email, warning: "Sent, but not added to the log: " + e.message.slice(0, 100) }); }
}

// The counters for "Email us a question" (instance "contact") and "Report Bugs" (instance "bugs", kind "bug"):
// one object each for the whole site, so every count is exact.
// Sign-in limits per IP address and per network (/24 or /64), and for the whole site (security review W4: codes asked
