const AUTH_LIMITS = { start: [[600, 10], [86400, 40]], verify: [[600, 20], [86400, 80]],
  save: [[60, 30], [86400, 300]], register: [[60, 30], [86400, 1500]], newacct: [[86400, 3]],
  addemail: [[3600, 5], [86400, 10]] };   // per IP (and per network); addemail also per account
