    const g = await env.CONTACT.get(env.CONTACT.idFromName("auth")).fetch("https://contact.internal/take", { method: "POST",
      body: JSON.stringify({ kind: "auth", what, keys: [...(ipOnly ? ["ip:" + ip] : ["ip:" + ip, "net:" + contactNetKey(ip)]), ...(extraKeys || [])] }) });
