    return new Response(null, { status: 302, headers: { location: clean.pathname + clean.search + clean.hash, "cache-control": "no-store", "referrer-policy": "no-referrer",
      "set-cookie": `pc_dev=${await devSign(env, "cookie", user, m[1], now() + DEV_COOKIE_S)}; Path=/device/${m[1]}/; HttpOnly; Secure; SameSite=Lax; Max-Age=${DEV_COOKIE_S}` } });
