    return new Response(TUNNEL_OFFLINE, { status: 503, headers: Object.fromEntries(Object.entries({ ...TUNNEL_PAGE_HEADERS,
      "content-security-policy": TUNNEL_PAGE_HEADERS["content-security-policy"].replace("frame-ancestors 'self'", `frame-ancestors https://${env.SITE_HOST || "planetcompute.ai"}`) }).filter(([k]) => k !== "x-frame-options")) });
  // a page of the program (HTML): a see-through corner label says it comes from the user's own computer through the
  // link (click-through, so it covers nothing); pictures, videos and API answers pass unchanged
