      `.pc-tunnel{position:fixed;top:0;right:0;width:250px;height:250px;overflow:hidden;pointer-events:none;z-index:2147483647}` +
      `.pc-tunnel span{position:absolute;top:84px;right:-80px;width:360px;transform:rotate(45deg);text-align:center;padding:5px 0;` +
      `background:rgba(7,91,120,.55);color:#ffd84d;font:700 11px/1.3 Inter,system-ui,sans-serif;letter-spacing:.03em;` +
      `box-shadow:0 2px 6px rgba(0,0,0,.25);text-shadow:0 1px 2px rgba(0,0,0,.6)}</style>` +
      `<div class="pc-tunnel" role="note" aria-label="Using a Tunnel to Your Local Machine (device ${m[1]})"><span>Using a Tunnel to Your Local Machine</span></div>`;
