// GET /api/admin/sherpa: every SherpaHub on the directory with its job progress and the accounts it credited
async function sherpaAdmin(env) {
  if (!env.SHERPA) return json({ hubs: [], jobs: [], rows: [] });
  const dir = sherpaStub(env, "sherpa:dir");
  const { hubs } = await (await dir.fetch("https://sherpa.internal/dir/list")).json();
  const { known } = await (await dir.fetch("https://sherpa.internal/dir/known")).json();
  const emails = new Map(), email = async (u) => {
    if (!u) return "";
    if (!emails.has(u)) { try { const p = await profile(env, u); emails.set(u, p.primary_email || (p.emails[0] || {}).email || ""); } catch (e) { emails.set(u, ""); } }
    return emails.get(u);
  };
  for (const h of hubs) {
    try { h.credits = (await (await sherpaStub(env, h.name).fetch("https://sherpa.internal/credits")).json()).accounts; } catch (e) { h.credits = []; }
    for (const c of h.credits) c.email = await email(c.user);
    h.email = await email(h.user);
  }
  const jobs = [];
  for (const name of Object.keys(known || {})) {
    try { for (const j of (await (await sherpaStub(env, name).fetch("https://sherpa.internal/jobs")).json()).jobs || []) jobs.push({ hub: name, ...j }); } catch (e) {}
  }
  jobs.sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
  const all = await listWorkhorses(env).catch(() => []), rows = all.filter((r) => r.role === "sherpahub");
  // every in-house server (workhorses, generous cows, SherpaHubs): the models on its copies (from its agent's reports)
  const servers = all.map((r) => ({ server_id: r.server_id, name: r.name, role: r.role || "", root_dir: r.root_dir, agent_seen_at: r.agent_seen_at, agent_state: r.agent_state }));
  return json({ hubs, jobs: jobs.slice(0, 200), rows, servers, secret_set: !!env.HB_SERVER_SECRET, max: SHERPA_HUBS_MAX });
}
const SHERPA_HUB_NAME = /^sherpa:hub:[A-Za-z0-9_-]{1,64}:[0-9a-f]{12}$/;
// The admin tab SherpaHubs: give work (a batch of prompts, or a matrix test job), cancel it, see where it went
async function sherpaAdminRoute(env, adminEmail, path, method, body, url) {
  if (!env.SHERPA) return json({ error: "SherpaHubs are not switched on." }, 503);
  if (path === "/api/admin/sherpa/job" && method === "GET") {        // one job: every prompt, who did it, the checks, the log
    const hub = url.searchParams.get("hub") || "", id = url.searchParams.get("id") || "";
    if (!SHERPA_HUB_NAME.test(hub) || !/^[0-9a-f]{16}$/.test(id)) return json({ error: "Bad hub or job." }, 400);
    const r = await sherpaStub(env, hub).fetch("https://sherpa.internal/jobs?id=" + id), d = await r.json();
    if (!r.ok) return json(d, r.status);
    const cache = new Map(), email = async (u) => { if (!u) return ""; if (!cache.has(u)) { try { const p = await profile(env, u); cache.set(u, p.primary_email || ""); } catch (e) { cache.set(u, ""); } } return cache.get(u); };
    for (const it of d.job.items || []) for (const x of [it.result, it.check]) if (x && x.who) x.who.email = await email(x.who.user);
    for (const x of d.devices || []) x.email = await email(x.user);
    return json({ hub, ...d });
  }
  if (path === "/api/admin/sherpa/file" && method === "GET") {       // a result file (private: sherpa_jobs/ in B2)
    const key = url.searchParams.get("key") || "";
    if (!/^sherpa_jobs\/[0-9a-f]{16}\/\d{1,3}-[01]\.(png|webm)$/.test(key)) return json({ error: "Bad file." }, 400);
    const b = await b2WriteAuth(env).catch(() => null);
    if (!b) return json({ error: "B2 is not available." }, 503);
    const r = await fetch(`${b.dl}/file/${b.bucket}/${key}`, { headers: { authorization: b.token } });
    if (!r.ok) return json({ error: "Not found." }, 404);
    return new Response(r.body, { headers: { "content-type": key.endsWith(".png") ? "image/png" : "video/webm", "cache-control": "private, max-age=3600" } });
  }
  if (path === "/api/admin/sherpa/log" && method === "GET") {         // the hub's own log lines, drain state
    const hub = url.searchParams.get("hub") || "";
    if (!SHERPA_HUB_NAME.test(hub)) return json({ error: "Bad hub." }, 400);
    return json(await (await sherpaStub(env, hub).fetch("https://sherpa.internal/hublog")).json());
  }
  if (path === "/api/admin/sherpa/drain" && method === "POST") {
    if (!SHERPA_HUB_NAME.test(String(body.hub || ""))) return json({ error: "Bad hub." }, 400);
    return json(await (await sherpaStub(env, body.hub).fetch("https://sherpa.internal/drain", { method: "POST", body: JSON.stringify({ on: !!body.on }) })).json());
  }
  if (path === "/api/admin/sherpa/cancel" && method === "POST") {
    if (!SHERPA_HUB_NAME.test(String(body.hub || "")) || !/^[0-9a-f]{16}$/.test(String(body.id || ""))) return json({ error: "Bad hub or job." }, 400);
    const r = await sherpaStub(env, body.hub).fetch("https://sherpa.internal/jobs/cancel", { method: "POST", body: JSON.stringify({ id: body.id, by: adminEmail }) });
    return json(await r.json(), r.status);
  }
  if (path === "/api/admin/sherpa/jobs" && method === "POST") {      // new work
    const j = { by: adminEmail, kind: body.kind === "matmul" ? "matmul" : "prompts" };
    if (j.kind === "matmul") {
      const n = (v, d) => (v === "" || v == null ? d : Number(v));
      Object.assign(j, { m: n(body.m, 2048), k: n(body.k, 4096), n: n(body.n, 2048), tile: n(body.tile, 64) });
      const ok = [j.m, j.k, j.n, j.tile].every(Number.isInteger) && j.k >= 1 && j.k <= 4096 && j.m >= 1 && j.n >= 1 && j.m <= 1048576 && j.n <= 1048576 &&
        j.tile >= 8 && j.tile <= 1024 && j.tile * j.k + 64 <= SHERPA_MAX_MSG && j.tile * j.tile * 4 + 64 <= SHERPA_MAX_MSG && Math.ceil(j.m / j.tile) * Math.ceil(j.n / j.tile) <= 2 ** 26;
      if (!ok) return json({ error: "Matrix job out of limits: K 1-4096, M and N up to 1,048,576, tile 8-1024 (tile x K and a tile of results must fit 1 MiB)." }, 400);
      j.total = Math.ceil(j.m / j.tile) * Math.ceil(j.n / j.tile); j.done = 0;
    } else {
      j.task = body.task === "image" ? "image" : "chat";
      j.model = String(body.model || "");
      if (!/^[\w.:+-]{1,80}$/.test(j.model)) return json({ error: "Choose a model." }, 400);
      const prompts = (Array.isArray(body.prompts) ? body.prompts : String(body.prompts || "").split("\n")).map((x) => String(x).trim()).filter(Boolean);
      if (!prompts.length) return json({ error: "Write at least one prompt (one per line)." }, 400);
      if (prompts.length > SHERPA_MAX_PROMPTS) return json({ error: `At most ${SHERPA_MAX_PROMPTS} prompts in one batch.` }, 400);
      if (prompts.some((x) => x.length > 2000)) return json({ error: "A prompt is longer than 2,000 characters." }, 400);
      j.prompts = prompts;
      j.check_pct = Math.max(0, Math.min(100, Math.round(Number(body.check_pct === "" || body.check_pct == null ? 10 : body.check_pct)) || 0));
      const P = {};
      if (j.task === "chat") P.max_tokens = Math.max(16, Math.min(2048, Number(body.max_tokens) || 512));
      else {
        const sz = (v, d) => { const x = Number(v) || d; return Math.max(128, Math.min(2048, Math.round(x / 2) * 2)); };
        P.width = sz(body.width, 512); P.height = sz(body.height, 512);
        if (Number(body.steps) > 0) P.steps = Math.min(100, Math.round(Number(body.steps)));
      }
      P.seed = Number.isInteger(Number(body.seed)) && body.seed !== "" ? Number(body.seed) : Math.floor(Math.random() * 2 ** 31);
      j.params = P;
    }
    let hub = String(body.hub || "");
    if (hub && !SHERPA_HUB_NAME.test(hub)) return json({ error: "Bad hub." }, 400);
    if (!hub) {                                                    // any: the running hub with the fewest jobs waiting
      const { hubs } = await (await sherpaStub(env, "sherpa:dir").fetch("https://sherpa.internal/dir/list")).json();
      const ready = hubs.filter((h) => !h.draining).sort((a, b) => (a.queued || 0) - (b.queued || 0));
      if (!ready.length) return json({ error: hubs.length ? "Every running SherpaHub is draining: undrain one first." : "No SherpaHub is running: start one on this tab first." }, 409);
      hub = ready[0].name;
    }
    const r = await sherpaStub(env, hub).fetch("https://sherpa.internal/jobs/add", { method: "POST", body: JSON.stringify(j) });
    return json({ hub, ...(await r.json()) }, r.status);
  }
  return json({ error: "Not found." }, 404);
}
async function b2PutBytes(b, key, data, ct) {
  const sha1 = [...new Uint8Array(await crypto.subtle.digest("SHA-1", data))].map((x) => x.toString(16).padStart(2, "0")).join("");
  const up = await (await fetch(`${b.api}/b2api/v3/b2_get_upload_url`, { method: "POST", headers: { authorization: b.token }, body: JSON.stringify({ bucketId: b.bucketId }) })).json();
  const r = await fetch(up.uploadUrl, { method: "POST", body: data, headers: { authorization: up.authorizationToken, "X-Bz-File-Name": encodeURIComponent(key),
    "Content-Type": ct, "X-Bz-Content-Sha1": sha1 } });
  if (!r.ok) throw new Error("b2 upload " + r.status);
}
